const COMMON_QUIZ_6 = [
  // ========== 自然地理（1-100） ==========
  { q: "地球自转的方向是？", options: ["自西向东", "自东向西", "自南向北", "自北向南"], answer: 0, explanation: "地球绕地轴自西向东自转，自转周期约为24小时（一个恒星日为23小时56分4秒）。自西向东的自转方向决定了天体周日视运动的方向，也使得地球上的物体在自转过程中受到地转偏向力的作用。" },
  { q: "地球自转一周的时间约为？", options: ["12小时", "24小时", "48小时", "365天"], answer: 1, explanation: "地球自转一周的时间约为24小时（太阳日），这是连续两次太阳经过同一子午线的时间间隔。恒星日为23小时56分4秒，是地球相对远处恒星自转一周的时间。" },
  { q: "地球公转一周的时间约为？", options: ["24小时", "30天", "365天", "100天"], answer: 2, explanation: "地球绕太阳公转一周约为365.25天（一个回归年），即365天5小时48分46秒。公转导致了四季更替和昼夜长短变化。公转轨道为近似椭圆，平均距太阳约1.5亿公里。" },
  { q: "黄赤交角的度数约为？", options: ["23.5°", "45°", "66.5°", "0°"], answer: 0, explanation: "黄赤交角即黄道面与赤道面的夹角，约为23.5°（精确值为23°26'）。黄赤交角的存在导致太阳直射点在南北回归线之间移动，从而形成了四季更替和昼夜长短变化。" },
  { q: "北回归线的纬度约为？", options: ["23.5°N", "23.5°S", "66.5°N", "0°"], answer: 0, explanation: "北回归线位于北纬23.5°，是太阳直射北半球的最北界线。每年夏至日（6月22日前后），太阳直射北回归线，北半球白昼最长。" },
  { q: "南回归线的纬度约为？", options: ["23.5°S", "23.5°N", "66.5°S", "0°"], answer: 0, explanation: "南回归线位于南纬23.5°，是太阳直射南半球的最南界线。每年冬至日（12月22日前后），太阳直射南回归线，南半球白昼最长。" },
  { q: "北极圈的纬度约为？", options: ["66.5°N", "23.5°N", "90°N", "45°N"], answer: 0, explanation: "北极圈位于北纬66.5°，是北半球有极昼极夜现象的南界。在北极圈以北的地区，夏季会出现极昼（太阳永不落下），冬季会出现极夜（太阳永不升起）。" },
  { q: "夏至日时，太阳直射点位于？", options: ["北回归线", "南回归线", "赤道", "北极圈"], answer: 0, explanation: "夏至日（6月22日前后），太阳直射北回归线（23.5°N），北半球白昼最长、黑夜最短，北极圈以北出现极昼。此时也是北半球夏季的开始。" },
  { q: "冬至日时，太阳直射点位于？", options: ["南回归线", "北回归线", "赤道", "北极圈"], answer: 0, explanation: "冬至日（12月22日前后），太阳直射南回归线（23.5°S），北半球白昼最短、黑夜最长，北极圈以北出现极夜。此时也是北半球冬季的开始。" },
  { q: "春分日和秋分日时，太阳直射点位于？", options: ["赤道", "北回归线", "南回归线", "北极圈"], answer: 0, explanation: "春分日（3月21日前后）和秋分日（9月23日前后），太阳直射赤道，全球各地昼夜平分，各12小时。春分后太阳直射点北移，秋分后太阳直射点南移。" },
  { q: "地球自转产生的地理意义不包括？", options: ["昼夜更替", "地方时差异", "四季变化", "水平运动物体的偏向"], answer: 2, explanation: "地球自转产生昼夜更替、地方时差异、沿地表水平运动物体的地转偏向力等。四季变化是由地球公转和黄赤交角共同导致的，不属于自转的地理意义。" },
  { q: "地球上昼夜更替现象产生的原因是？", options: ["地球自转", "地球公转", "黄赤交角", "地轴倾斜"], answer: 0, explanation: "昼夜更替是由地球自转产生的。地球是一个不发光、不透明的球体，太阳只能照亮半个地球，随着地球自转，昼夜不断交替。昼夜更替周期为24小时，使地表温度不至于过高或过低。" },
  { q: "在北半球，水平运动的物体受地转偏向力的影响会？", options: ["向右偏", "向左偏", "不偏转", "向上偏"], answer: 0, explanation: "由于地球自转，北半球水平运动的物体受到地转偏向力的作用向右偏转，南半球向左偏转。赤道上不发生偏转。这一规律对大气环流、洋流走向和河流侵蚀都有重要影响。" },
  { q: "北京时间采用的是哪个时区的区时？", options: ["东八区", "东六区", "东九区", "中时区"], answer: 0, explanation: "北京时间采用东八区（120°E）的区时作为全国统一标准时间。中国领土跨度大，横跨东五区到东九区共5个时区，但为方便管理统一使用东八区时间。" },
  { q: "全球共划分为多少个时区？", options: ["12个", "24个", "36个", "48个"], answer: 1, explanation: "全球按经度每15°为一个时区，共划分24个时区。以0°经线为中时区，向东向西各12个时区，东十二区和西十二区各占7.5°，合并为一个时区。每个相邻时区相差1小时。" },
  { q: "国际上规定日界线大致沿哪条经线？", options: ["180°经线", "0°经线", "120°经线", "60°经线"], answer: 0, explanation: "国际日期变更线（日界线）大致沿180°经线绘制，但为了不穿越陆地，在某些地方有弯曲。自西向东越过日界线日期减一天，自东向西越过日期加一天。" },
  { q: "东经120°所在时区是？", options: ["东八区", "东七区", "东九区", "东六区"], answer: 0, explanation: "时区计算方法：经度÷15°，东经为东时区，西经为西时区。120°÷15°=8，所以东经120°位于东八区。东八区的中央经线为120°E，区时即为120°E的地方时。" },
  { q: "当东八区为8月3日10时时，西五区的时间是？", options: ["8月2日21时", "8月3日21时", "8月2日23时", "8月3日1时"], answer: 0, explanation: "东八区与西五区相差13个时区（8+5=13），即西五区比东八区晚13小时。东八区10时减去13小时=前一日21时，即8月2日21时。" },
  { q: "对流层大气的主要直接热源是？", options: ["太阳辐射", "地面辐射", "大气逆辐射", "太阳活动"], answer: 1, explanation: "对流层大气的热量主要来自地面辐射，而非直接吸收太阳辐射。太阳辐射首先加热地面，地面再通过辐射、对流、湍流等方式将热量传递给近地面大气，因此对流层气温随高度增加而降低。" },
  { q: "对流层的主要特点是？", options: ["气温随高度增加而升高", "气温随高度增加而降低", "天气现象少", "空气以水平运动为主"], answer: 1, explanation: "对流层气温随高度增加而降低（每升高1000米下降约6°C），空气以对流运动为主，集中了几乎全部水汽和固体杂质，云、雨、雪等天气现象都发生在对流层。" },
  { q: "平流层气温随高度增加而升高的原因是？", options: ["地面辐射", "臭氧吸收紫外线", "空气对流", "水汽凝结"], answer: 1, explanation: "平流层含有大量臭氧，臭氧能吸收太阳紫外线，将紫外辐射转化为热能，因此平流层气温随高度增加而升高。平流层大气以水平运动为主，天气现象少，适合飞机飞行。" },
  { q: "大气的最底层是？", options: ["对流层", "平流层", "中间层", "热层"], answer: 0, explanation: "大气自下而上分为对流层、平流层、中间层、热层（电离层）和外层（散逸层）。对流层是最底层，平均厚度约10-12公里，集中了约75%的大气质量和几乎全部水汽。" },
  { q: "人类活动主要影响的大气层是？", options: ["对流层", "平流层", "中间层", "热层"], answer: 0, explanation: "人类活动主要影响对流层，因为人类生活在对流层底部。工厂废气、汽车尾气等排放到对流层中，造成大气污染、雾霾等环境问题。但人类活动也会通过氟利昂等物质破坏平流层臭氧层。" },
  { q: "臭氧层主要存在于大气的哪个层次？", options: ["对流层", "平流层", "中间层", "热层"], answer: 1, explanation: "臭氧层主要存在于平流层中，距地面约20-30公里处。臭氧层能吸收大部分太阳紫外线，保护地球生物免受紫外线伤害。氟利昂等物质的排放会破坏臭氧层，形成臭氧空洞。" },
  { q: "下列不属于大气受热过程的是？", options: ["太阳辐射", "地面辐射", "大气逆辐射", "地壳运动"], answer: 3, explanation: "大气受热过程包括：太阳辐射加热地面（地面吸收太阳辐射增温）、地面辐射加热大气（大气主要直接热源）、大气逆辐射对地面的保温作用。地壳运动属于内力作用，与大气受热过程无关。" },
  { q: "大气逆辐射的地理意义是？", options: ["使大气增温", "对地面起到保温作用", "使地面降温", "减少太阳辐射"], answer: 1, explanation: "大气逆辐射是指大气将吸收的热量再次向地面辐射的过程，其方向指向地面。大气逆辐射对地面起到保温作用，使地面温度不至过低。多云的夜晚比晴朗夜晚温度高，就是大气逆辐射强的表现。" },
  { q: "下列哪种气候类型全年高温多雨？", options: ["热带雨林气候", "地中海气候", "温带季风气候", "热带沙漠气候"], answer: 0, explanation: "热带雨林气候全年高温多雨，全年各月气温在25°C以上，年降水量在2000mm以上且各月分配均匀。主要分布在赤道附近，如亚马逊平原、刚果盆地和东南亚群岛等地。" },
  { q: "地中海气候的主要特征是？", options: ["全年高温多雨", "夏季炎热干燥，冬季温和多雨", "夏季高温多雨，冬季寒冷干燥", "全年温和湿润"], answer: 1, explanation: "地中海气候的特征是夏季炎热干燥、冬季温和多雨。夏季受副热带高压控制，干燥少雨；冬季受西风带控制，温和多雨。主要分布在地中海沿岸、加州、南非开普敦等地。" },
  { q: "温带季风气候的典型特征是？", options: ["全年高温多雨", "夏季高温多雨，冬季寒冷干燥", "夏季炎热干燥，冬季温和多雨", "全年温和湿润"], answer: 1, explanation: "温带季风气候夏季高温多雨、冬季寒冷干燥，主要分布在东亚地区（中国秦岭-淮河以北、朝鲜半岛、日本北部等）。夏季受来自海洋的东南季风影响，冬季受来自大陆的西北季风影响。" },
  { q: "温带海洋性气候的主要特征是？", options: ["全年高温多雨", "夏季炎热干燥，冬季温和多雨", "全年温和湿润，降水均匀", "夏季高温多雨，冬季寒冷干燥"], answer: 2, explanation: "温带海洋性气候全年温和湿润，各月降水较均匀，气温年较差小。主要分布在中纬度大陆西岸，如西欧（英国、荷兰等），受盛行西风和北大西洋暖流影响。" },
  { q: "热带草原气候的降水特点是？", options: ["全年多雨", "干湿季分明", "全年少雨", "冬季多雨"], answer: 1, explanation: "热带草原气候全年高温（最冷月20°C以上），干湿季分明。夏季受赤道低气压带控制多雨，冬季受信风带控制干燥。主要分布在热带雨林气候南北两侧，如非洲草原、巴西高原等。" },
  { q: "热带沙漠气候的主要特征是？", options: ["全年高温多雨", "全年炎热干燥", "夏季炎热干燥，冬季温和多雨", "全年温和湿润"], answer: 1, explanation: "热带沙漠气候全年炎热干燥，降水量极少（不足250mm），蒸发量远大于降水量。主要分布在南北回归线附近的大陆内部和西岸，如撒哈拉沙漠、阿拉伯半岛等。" },
  { q: "亚热带季风气候的特征是？", options: ["夏季高温多雨，冬季温和少雨", "全年高温多雨", "夏季炎热干燥，冬季温和多雨", "全年温和湿润"], answer: 0, explanation: "亚热带季风气候夏季高温多雨、冬季温和少雨（最冷月0°C以上）。主要分布在中国秦岭-淮河以南、日本南部、美国东南部等地区。雨热同期有利于水稻等作物生长。" },
  { q: "下列气候类型中，分布在赤道两侧的是？", options: ["热带雨林气候", "地中海气候", "温带季风气候", "极地气候"], answer: 0, explanation: "热带雨林气候分布在赤道两侧（南北纬10°以内），全年受赤道低压带控制，高温多雨。主要分布在亚马逊平原、刚果盆地和马来群岛等地，植被为热带雨林。" },
  { q: "赤道低气压带的控制地区降水特点是？", options: ["多雨", "少雨", "干燥", "干湿交替"], answer: 0, explanation: "赤道低气压带地区空气上升运动强烈，水汽易凝结成云致雨，形成多雨天气。热带雨林气候即全年受赤道低气压带控制，年降水量可达2000mm以上。" },
  { q: "副热带高压带控制下的天气特征是？", options: ["多雨", "干燥少雨", "温和多雨", "暴风雨"], answer: 1, explanation: "副热带高压带（约30°N/S附近）地区空气下沉运动，下沉过程中增温，水汽不易凝结，形成干燥少雨天气。世界主要沙漠（撒哈拉、阿拉伯等）多分布在此区域。" },
  { q: "盛行西风带分布在哪个纬度范围内？", options: ["0°-30°", "30°-60°", "60°-90°", "10°-20°"], answer: 1, explanation: "盛行西风带分布在南北纬30°-60°之间，风向自西向东（西南风/西北风）。西风带将海洋水汽带向大陆，使中纬度大陆西岸形成温带海洋性气候，降水丰富。" },
  { q: "东北信风带分布在哪个纬度范围内？", options: ["0°-30°N", "30°-60°N", "60°-90°N", "0°-30°S"], answer: 0, explanation: "东北信风带分布在北半球0°-30°之间，风向由东北吹向西南。信风带气流从较高纬度吹向较低纬度，温度逐渐升高，水汽不易凝结，天气干燥少雨。" },
  { q: "气压带和风带的移动规律是？", options: ["随太阳直射点移动而移动", "固定不动", "随机移动", "自东向西移动"], answer: 0, explanation: "气压带和风带随太阳直射点的南北移动而移动，夏季北移、冬季南移，移动幅度约5°-10°。这种移动导致部分地区受不同气压带和风带交替控制，形成不同气候类型。" },
  { q: "季风形成的根本原因是？", options: ["海陆热力差异", "地形起伏", "洋流影响", "地球自转"], answer: 0, explanation: "季风形成的主要原因是海陆热力差异。夏季陆地增温快于海洋，形成低压，风从海洋吹向陆地（夏季风）；冬季陆地降温快于海洋，形成高压，风从陆地吹向海洋（冬季风）。气压带风带的季节移动也有影响。" },
  { q: "南亚季风的夏季风风向是？", options: ["东南风", "西南风", "东北风", "西北风"], answer: 1, explanation: "南亚夏季盛行西南季风。夏季太阳直射点北移，南半球的东南信风越过赤道，在地转偏向力作用下右偏成西南风，从印度洋带来大量水汽，形成南亚的雨季。" },
  { q: "东亚夏季风的风向是？", options: ["东南风", "西南风", "东北风", "西北风"], answer: 0, explanation: "东亚夏季盛行东南季风。夏季亚洲大陆形成低压（印度低压），太平洋形成高压（夏威夷高压），风从太平洋高压吹向亚洲大陆低压，在地转偏向力作用下右偏为东南风。" },
  { q: "水循环的类型不包括？", options: ["海上内循环", "陆地内循环", "海陆间循环", "大气内循环"], answer: 3, explanation: "水循环分为三种类型：海上内循环（海洋蒸发—降水回海洋）、陆地内循环（陆地蒸发蒸腾—降水回陆地）、海陆间大循环（海洋蒸发—水汽输送—陆地降水—径流回海洋）。没有大气内循环这一分类。" },
  { q: "水循环中最活跃的环节是？", options: ["蒸发", "降水", "地表径流", "水汽输送"], answer: 3, explanation: "水汽输送是水循环中最活跃的环节，它将海洋蒸发的水汽输送到陆地，是海陆间水循环的关键环节。大气环流将水汽从海洋输送到内陆，使陆地获得淡水资源。" },
  { q: "河流最主要的补给来源是？", options: ["大气降水", "冰川融水", "地下水", "湖泊水"], answer: 0, explanation: "大气降水是河流最主要的补给来源。世界上大多数河流以雨水补给为主，降水量的多少和季节分配直接影响河流水量和水位变化。热带和温带地区河流多为雨水补给。" },
  { q: "我国西北内陆地区河流的主要补给类型是？", options: ["雨水补给", "冰川融水补给", "地下水补给", "湖泊水补给"], answer: 1, explanation: "我国西北内陆地区气候干旱，降水稀少，河流主要靠高山冰川融水补给。冰川融水量随气温变化而变化，夏季气温高融水量大，河流出现汛期，冬季气温低则可能断流。" },
  { q: "以冰川融水为主要补给的河流，其流量最大季节是？", options: ["春季", "夏季", "秋季", "冬季"], answer: 1, explanation: "冰川融水补给河流的流量与气温密切相关。夏季气温最高，冰川融化量最大，河流流量最大；冬季气温低，冰川几乎不融化，河流流量最小甚至断流。如塔里木河夏季为汛期。" },
  { q: "以雨水补给为主的河流，其流量变化主要取决于？", options: ["气温变化", "降水量变化", "地形变化", "植被覆盖"], answer: 1, explanation: "雨水补给河流的流量变化与降水量变化密切相关。雨季降水多，河流流量增大出现汛期；旱季降水少，流量减小出现枯水期。如我国东部季风区河流汛期集中在夏季。" },
  { q: "下列关于洋流的说法，正确的是？", options: ["暖流的水温高于流经海区水温", "寒流的水温高于流经海区水温", "洋流只影响水温不影响气候", "洋流方向不受风向影响"], answer: 0, explanation: "暖流是指比流经海区水温高的洋流，寒流是比流经海区水温低的洋流。暖流对沿岸气候有增温增湿作用，寒流有降温减湿作用。洋流方向主要受盛行风、地转偏向力和陆地形状影响。" },
  { q: "下列洋流中属于暖流的是？", options: ["加利福尼亚寒流", "秘鲁寒流", "墨西哥湾暖流", "西澳大利亚寒流"], answer: 2, explanation: "墨西哥湾暖流（湾流）是世界上最强大的暖流之一，由南赤道暖流分支沿南美洲东岸北上，经墨西哥湾后沿北美东岸向东北流向欧洲，对西欧和北欧气候有显著的增温增湿作用。" },
  { q: "下列洋流中属于寒流的是？", options: ["北大西洋暖流", "黑潮", "秘鲁寒流", "阿拉斯加暖流"], answer: 2, explanation: "秘鲁寒流是南太平洋东部的寒流，由南美洲西海岸自南向北流动，属于南半球副热带环流的一部分。秘鲁寒流导致秘鲁沿海降温减湿，也使该海域上升流带来丰富营养盐，形成著名渔场。" },
  { q: "北太平洋西部的暖流名称是？", options: ["黑潮", "亲潮", "加利福尼亚寒流", "北太平洋暖流"], answer: 0, explanation: "黑潮（日本暖流）是北太平洋西部的强大暖流，源于北赤道暖流，沿菲律宾群岛东岸北上，经台湾东部、日本南岸向东北流去。黑潮对日本气候有显著的增温增湿作用。" },
  { q: "秘鲁渔场的形成主要原因是？", options: ["寒暖流交汇", "上升流带来营养盐", "河流入海带来营养盐", "海底地形"], answer: 1, explanation: "秘鲁渔场的形成主要得益于秘鲁沿海的上升流。深层海水上涌将海底营养盐带到表层，浮游生物大量繁殖，为鱼类提供丰富饵料，形成世界著名大渔场。" },
  { q: "纽芬兰渔场形成的主要原因是？", options: ["上升流", "寒暖流交汇", "河流入海", "大陆架浅"], answer: 1, explanation: "纽芬兰渔场位于加拿大东海岸，由拉布拉多寒流和墨西哥湾暖流交汇形成。寒暖流交汇使海水搅动，营养盐上涌，浮游生物繁殖，鱼类聚集形成大渔场。" },
  { q: "北海道渔场形成的主要原因是？", options: ["上升流", "寒暖流交汇", "河流入海", "大陆架浅"], answer: 1, explanation: "北海道渔场位于日本北海道附近，由亲潮（千岛寒流）和黑潮（日本暖流）交汇形成。寒暖流交汇带来丰富营养盐和浮游生物，是世界著名大渔场之一。" },
  { q: "世界六大板块中，几乎全部由海洋岩石圈组成的是？", options: ["太平洋板块", "亚欧板块", "非洲板块", "印度洋板块"], answer: 0, explanation: "六大板块中太平洋板块几乎全部由海洋岩石圈组成。其余五大板块（亚欧、非洲、印度洋、美洲、南极洲）都包含大陆和海洋两部分。板块交界处是地壳活动最活跃的地带。" },
  { q: "板块构造学说认为，板块的哪种运动形成海岭？", options: ["碰撞", "张裂", "平移", "俯冲"], answer: 1, explanation: "板块张裂运动形成海岭（大洋中脊）。板块在洋中脊处向两侧分离，岩浆涌出冷却形成新洋壳，如大西洋中脊。板块张裂还形成裂谷，如东非大裂谷。" },
  { q: "板块碰撞挤压运动通常形成？", options: ["海岭", "裂谷", "褶皱山脉", "海沟"], answer: 2, explanation: "板块碰撞挤压运动通常形成褶皱山脉。如亚欧板块与印度洋板块碰撞形成喜马拉雅山脉，太平洋板块与美洲板块碰撞形成安第斯山脉。板块碰撞带是地震和火山活动频发地带。" },
  { q: "世界两大地震带是？", options: ["环太平洋地震带和地中海-喜马拉雅地震带", "大西洋地震带和印度洋地震带", "北极地震带和南极地震带", "环太平洋地震带和大西洋地震带"], answer: 0, explanation: "世界两大地震带是环太平洋地震带和地中海-喜马拉雅地震带。环太平洋地震带集中了全球约80%的浅源地震和几乎全部的深源地震。两大地震带均位于板块交界处。" },
  { q: "喜马拉雅山脉是由哪两个板块碰撞形成的？", options: ["亚欧板块和印度洋板块", "太平洋板块和亚欧板块", "非洲板块和亚欧板块", "美洲板块和太平洋板块"], answer: 0, explanation: "喜马拉雅山脉由亚欧板块与印度洋板块（印度板块）碰撞挤压形成。两大板块持续碰撞使喜马拉雅山脉不断隆起升高，目前仍以每年约5毫米的速度上升。" },
  { q: "安第斯山脉的形成与哪两个板块的运动有关？", options: ["南极洲板块和美洲板块", "太平洋板块和美洲板块", "亚欧板块和太平洋板块", "非洲板块和美洲板块"], answer: 0, explanation: "安第斯山脉是南极洲板块俯冲到南美洲板块（美洲板块）下方碰撞挤压形成的。板块俯冲导致岩浆上涌形成火山，同时形成高大褶皱山脉，是世界上最长的山脉。" },
  { q: "下列关于东非大裂谷的说法，正确的是？", options: ["板块碰撞形成", "板块张裂形成", "河流侵蚀形成", "风力侵蚀形成"], answer: 1, explanation: "东非大裂谷是由非洲板块内部张裂运动形成的，被称为'地球的伤疤'。板块张裂使地壳下沉形成狭长谷地，未来可能进一步扩展形成新的海洋。" },
  { q: "日本多火山地震的原因是？", options: ["位于板块内部", "位于板块交界处", "地形低平", "气候湿润"], answer: 1, explanation: "日本位于亚欧板块、太平洋板块、北美板块和菲律宾板块的交界处，板块运动活跃，碰撞和俯冲频繁，因此多火山和地震。日本约占全球地震的10%，被称为'火山地震之国'。" },
  { q: "下列地貌中，由流水侵蚀作用形成的是？", options: ["峡谷", "沙丘", "风蚀蘑菇", "喀斯特地貌"], answer: 0, explanation: "峡谷主要由河流流水下切侵蚀形成，如长江三峡、雅鲁藏布大峡谷。河流在山区下切侵蚀形成深窄的V形谷，在平原区侧蚀形成宽浅的U形谷。喀斯特地貌为溶蚀作用形成。" },
  { q: "喀斯特地貌的主要形成原因是？", options: ["流水溶蚀", "风力侵蚀", "冰川侵蚀", "流水沉积"], answer: 0, explanation: "喀斯特地貌是可溶性岩石（石灰岩等）在含二氧化碳的流水溶蚀作用下形成的地貌，包括溶洞、石林、峰林、天坑等。中国云南石林、广西桂林山水是典型喀斯特地貌。" },
  { q: "下列地貌中，由风力沉积作用形成的是？", options: ["沙丘", "冲积平原", "三角洲", "冰碛丘陵"], answer: 0, explanation: "沙丘由风力沉积作用形成，主要分布在干旱和半干旱地区。风将沙粒搬运到一定距离后，风力减弱，沙粒沉积形成沙丘。沙丘的缓坡为迎风坡，陡坡为背风坡。" },
  { q: "冲积平原的形成原因是？", options: ["风力沉积", "流水沉积", "冰川沉积", "风力侵蚀"], answer: 1, explanation: "冲积平原是由河流流水沉积作用形成的。河流流经平原时流速减慢，搬运的泥沙逐渐沉积形成宽广平坦的冲积平原，如长江中下游平原、华北平原等。河流中下游和入海口处沉积作用最显著。" },
  { q: "下列属于河流堆积地貌的是？", options: ["V形谷", "瀑布", "三角洲", "峡谷"], answer: 2, explanation: "三角洲属于河流堆积地貌，形成于河流入海口或入湖口。河流在入海处流速骤减，泥沙大量沉积形成三角形的堆积体。V形谷、峡谷和瀑布均为侵蚀地貌。" },
  { q: "黄土高原沟壑纵横的地貌成因主要是？", options: ["风力侵蚀", "流水侵蚀", "冰川侵蚀", "风力沉积"], answer: 1, explanation: "黄土高原沟壑纵横的地貌主要是由流水侵蚀形成的。黄土土质疏松，夏季暴雨冲刷严重，长期流水侵蚀形成大量沟壑。黄土本身是风力从西北沙漠搬运沉积的，但沟壑地形为流水侵蚀形成。" },
  { q: "下列属于海岸侵蚀地貌的是？", options: ["海积沙滩", "海蚀崖", "河口三角洲", "海岸平原"], answer: 1, explanation: "海蚀崖是海岸侵蚀地貌，由海浪不断侵蚀海岸基岩形成。海浪通过水力冲击和携带沙砾磨蚀海岸，形成陡峭的海蚀崖。海积沙滩和三角洲属于堆积地貌。" },
  { q: "下列土壤类型中，在我国南方地区广泛分布的是？", options: ["黑土", "红壤", "黄土", "灰化土"], answer: 1, explanation: "红壤在我国南方热带和亚热带地区广泛分布。高温多雨条件下，土壤中可溶性盐基离子被淋失，铁铝氧化物相对富集，使土壤呈红色。红壤酸性强、肥力较低，需改良后利用。" },
  { q: "下列土壤中，有机质含量最高的是？", options: ["红壤", "黑土", "黄壤", "砖红壤"], answer: 1, explanation: "黑土有机质含量最高，主要分布在我国东北平原。冷湿气候条件下，植被枯枝落叶分解缓慢，大量有机质积累，使土壤呈黑色。黑土肥力高，是重要的农业土壤，有'土中之王'之称。" },
  { q: "紫色土主要分布在我国哪个地区？", options: ["东北平原", "四川盆地", "黄土高原", "云贵高原"], answer: 1, explanation: "紫色土主要分布在四川盆地，由紫红色砂岩和页岩风化形成。紫色土富含磷、钾等矿物养分，自然肥力较高，是四川盆地重要的农业土壤，适合种植水稻、油菜等作物。" },
  { q: "黄土主要分布在我国的哪个地区？", options: ["东北平原", "黄土高原", "四川盆地", "云贵高原"], answer: 1, explanation: "黄土主要分布在黄土高原地区，是风力从西北戈壁沙漠搬运来的粉尘沉积形成。黄土土质疏松、垂直节理发育，易受流水侵蚀，是造成黄土高原水土流失严重的重要原因。" },
  { q: "下列关于土壤形成因素的叙述，正确的是？", options: ["成土母质是土壤有机质的来源", "气候直接影响土壤水热状况", "地形不影响土壤发育", "人类活动对土壤形成无影响"], answer: 1, explanation: "气候直接影响土壤的水热状况，影响土壤中物质的转化和迁移，是土壤形成的重要因素。成土母质是土壤矿物养分的主要来源；地形影响水热分布间接影响土壤发育；人类活动如耕作、施肥等对土壤有重要影响。" },
  { q: "地球的形状是？", options: ["正球体", "扁球体", "不规则椭球体", "正方体"], answer: 2, explanation: "地球是一个两极稍扁、赤道略鼓的不规则椭球体。赤道半径约6378公里，极半径约6357公里，相差约21公里。由于地球自转的离心力，赤道部分略鼓。" },
  { q: "地球的平均半径约为？", options: ["6371公里", "6378公里", "6357公里", "6400公里"], answer: 0, explanation: "地球的平均半径约为6371公里。赤道半径约6378公里，极半径约6357公里。地球赤道周长约40076公里，表面积约5.1亿平方公里。" },
  { q: "经线的特点描述正确的是？", options: ["指示东西方向", "指示南北方向", "相互平行", "都是圆圈"], answer: 1, explanation: "经线（子午线）是连接南北两极的半圆线，指示南北方向，所有经线长度相等。经线从0°到180°分为东经和西经，以0°经线（本初子午线）为起算线。" },
  { q: "纬线的特点描述正确的是？", options: ["指示南北方向", "指示东西方向", "都是半圆", "长度都相等"], answer: 1, explanation: "纬线是平行于赤道的圆圈，指示东西方向，长度从赤道向两极递减。赤道是最长的纬线（约40076公里），到两极缩为一点。纬线相互平行，不相交。" },
  { q: "0°经线又称为什么？", options: ["本初子午线", "国际日期变更线", "赤道", "回归线"], answer: 0, explanation: "0°经线称为本初子午线，是经度起算线，通过英国伦敦格林尼治天文台原址。从本初子午线向东为东经，向西为西经，各到180°。1884年国际经度会议确定本初子午线。" },
  { q: "赤道的纬度是？", options: ["0°", "23.5°", "66.5°", "90°"], answer: 0, explanation: "赤道纬度为0°，是南北纬的分界线，也是地球上最长的纬线，周长约40076公里。赤道以北为北纬（N），以南为南纬（S），各到90°。赤道地区终年高温多雨。" },
  { q: "地球上白昼最长的一天在北半球是？", options: ["春分日", "夏至日", "秋分日", "冬至日"], answer: 1, explanation: "北半球夏至日（6月22日前后）白昼最长、黑夜最短。夏至日太阳直射北回归线，北半球各地白昼时间达到一年中最大值，北极圈以北出现极昼。" },
  { q: "秋分日时，太阳直射点的位置和移动方向是？", options: ["赤道，向南移动", "赤道，向北移动", "北回归线，向南移动", "南回归线，向北移动"], answer: 0, explanation: "秋分日（9月23日前后）太阳直射赤道，此后太阳直射点向南移动。秋分日全球昼夜等长。从秋分到冬至，太阳直射点从赤道移到南回归线，北半球白昼逐渐变短。" },
  { q: "下列哪种现象是地球公转产生的？", options: ["昼夜更替", "地方时差异", "四季变化", "水平运动物体的偏转"], answer: 2, explanation: "地球公转和黄赤交角共同产生四季变化、昼夜长短变化、正午太阳高度变化等现象。昼夜更替、地方时差异和地转偏向力是地球自转产生的。" },
  { q: "某地正午太阳高度为90°，说明该地位于？", options: ["赤道", "太阳直射点", "回归线", "极圈"], answer: 1, explanation: "正午太阳高度为90°说明该地正处于太阳直射点上。太阳直射点在南北回归线之间移动，直射点处正午太阳高度为90°，是全年最大值。离开直射点越远，正午太阳高度越小。" },
  { q: "北京的正午太阳高度达到一年中最大值的时间是？", options: ["春分日", "夏至日", "秋分日", "冬至日"], answer: 1, explanation: "北京位于北纬约40°，夏至日太阳直射北回归线，距北京最近，因此夏至日北京正午太阳高度达到全年最大值。冬至日太阳直射南回归线，距北京最远，正午太阳高度为全年最小。" },
  { q: "下列关于五带的说法，正确的是？", options: ["热带位于南北回归线之间", "温带位于回归线与极圈之间", "寒带位于极圈以内", "以上都对"], answer: 3, explanation: "五带划分：热带（南北回归线之间）、北温带（北回归线到北极圈之间）、南温带（南回归线到南极圈之间）、北寒带（北极圈以内）、南寒带（南极圈以内）。热带有直射阳光，温带四季分明，寒带有极昼极夜。" },
  { q: "下列关于晨昏线的说法，正确的是？", options: ["晨昏线永远与经线圈重合", "春分秋分日晨昏线与经线圈重合", "夏至日晨昏线与经线圈重合", "冬至日晨昏线与经线圈重合"], answer: 1, explanation: "春分日和秋分日时太阳直射赤道，晨昏线（昼夜分界线）与经线圈重合，全球昼夜等长。其他时间晨昏线与经线圈不重合，昼夜不等长。夏至冬至日时晨昏线偏离最大。" },
  { q: "大气对太阳辐射的削弱作用不包括？", options: ["吸收", "反射", "散射", "折射"], answer: 3, explanation: "大气对太阳辐射的削弱作用包括吸收（臭氧吸收紫外线、水汽和CO2吸收红外线）、反射（云层反射）、散射（分子散射和粗粒散射）。折射不是削弱作用，只是改变光传播方向。" },
  { q: "晴朗的天空呈现蓝色，原因是？", options: ["大气吸收", "大气反射", "大气散射", "大气折射"], answer: 2, explanation: "晴朗天空呈蓝色是大气散射的结果。太阳辐射经过大气层时，空气分子对波长较短的蓝紫色光散射最强（瑞利散射），使天空呈现蓝色。日出日落时天空呈红色是因为光线穿过更厚的大气层，蓝光被散射殆尽只剩红光。" },
  { q: "下列关于大气的保温作用的叙述，正确的是？", options: ["大气逆辐射对地面有保温作用", "大气不吸收地面辐射", "云越多夜晚温度越低", "大气逆辐射只发生在白天"], answer: 0, explanation: "大气逆辐射将部分热量返还给地面，起到保温作用。大气中的水汽和CO2强烈吸收地面长波辐射而增温，然后向地面辐射热量。多云的夜晚大气逆辐射强，温度比晴朗夜晚高。" },
  { q: "下列关于气温日变化的叙述，正确的是？", options: ["最高气温出现在正午12点", "最高气温出现在14点前后", "最低气温出现在日出前", "以上都不对"], answer: 1, explanation: "一天中最高气温出现在14点前后。虽然正午太阳辐射最强，但地面蓄热需时间，约午后13点地面温度最高，大气再吸收热量增温需1小时左右，因此气温最高在14点前后。最低温在日出前。" },
  { q: "下列关于气温水平分布的叙述，正确的是？", options: ["气温从低纬向高纬递减", "气温从高纬向低纬递减", "气温与纬度无关", "全球气温均匀分布"], answer: 0, explanation: "全球气温总体从低纬向高纬递减，因为低纬地区太阳高度角大、辐射强。但海洋和陆地、海拔高低、洋流寒暖等因素也会影响气温分布。等温线在陆地上弯曲较大，在海洋上较平直。" },
  { q: "下列因素中，不属于影响气温分布因素的是？", options: ["纬度", "海陆位置", "地形", "人口密度"], answer: 3, explanation: "影响气温分布的主要因素有纬度（太阳辐射量）、海陆位置（海洋比热大调节气温）、地形（海拔每升1000米降6°C）、洋流（暖流增温寒流降温）。人口密度不直接影响气温分布。" },
  { q: "下列关于降水的叙述，正确的是？", options: ["降水必须要有水汽和凝结核", "降水只发生在对流层", "降水量的单位是摄氏度", "赤道地区降水最少"], answer: 0, explanation: "降水形成的三个条件：充足的水汽、凝结核（固体微粒）、上升运动（降温促使水汽凝结）。降水单位是毫米。赤道地区因上升气流强而降水最多。降水主要发生在对流层。" },
  { q: "下列关于世界降水量分布的叙述，正确的是？", options: ["赤道地区降水最多", "回归线两侧均多雨", "中纬度内陆降水多", "两极地区降水多"], answer: 0, explanation: "赤道地区受赤道低压带控制，上升气流强，降水最多。回归线两侧受副热带高压控制，降水少（沙漠广布）。中纬度内陆远离海洋水汽稀少。两极地区下沉气流为主，降水稀少。" },
  { q: "锋面雨是我国最主要的降水类型，其形成原因是？", options: ["气流受地形抬升", "冷暖空气交汇", "空气对流上升", "台风影响"], answer: 1, explanation: "锋面雨是冷暖空气交汇（锋面）时，暖空气被抬升冷却，水汽凝结形成的降水。我国大部分地区受季风影响，冷暖气团频繁交汇形成锋面雨，是我国最主要的降水类型。" },
  { q: "下列关于对流雨的叙述，正确的是？", options: ["多发生在夏季午后", "持续时间长", "强度小", "多发生在冬季"], answer: 0, explanation: "对流雨多发生在夏季午后，由于近地面空气强烈受热膨胀上升，水汽凝结形成降水。对流雨强度大、持续时间短、范围小，常伴有雷电。赤道地区每日午后多对流雨。" },
  { q: "地形雨多发生在？", options: ["平原地区", "山地迎风坡", "山地背风坡", "盆地内部"], answer: 1, explanation: "地形雨发生在山地迎风坡。暖湿气流被山地阻挡被迫抬升，随海拔升高气温下降，水汽凝结形成降水。迎风坡降水多，背风坡因气流下沉增温而干燥少雨（雨影效应）。" },
  { q: "下列关于气旋与反气旋的叙述，正确的是？", options: ["北半球气旋逆时针方向", "北半球反气旋逆时针方向", "气旋中心气压高", "反气旋中心气压低"], answer: 0, explanation: "北半球气旋（低压）气流逆时针辐合上升，多阴雨天气；北半球反气旋（高压）气流顺时针辐散下沉，多晴朗天气。南半球方向相反。气旋中心气压低，反气旋中心气压高。" },
  { q: "下列关于冷锋的叙述，正确的是？", options: ["暖空气主动推冷空气", "冷空气主动推暖空气", "冷暖空气势均力敌", "冷锋过境后气温升高"], answer: 1, explanation: "冷锋是冷气团主动推动暖气团前进形成的锋面。冷锋过境时常出现大风、降温、降水（暴雨或大雪）天气。冷锋过境后气压升高、气温下降、天气转晴。我国北方夏季暴雨多为冷锋形成。" },
  { q: "下列关于暖锋的叙述，正确的是？", options: ["暖空气主动推冷空气", "过境后气温降低", "过境时常出现大风", "多出现在冬季"], answer: 0, explanation: "暖锋是暖气团主动推动冷气团前进形成的锋面。暖锋过境时常出现连续性降水，云系从高到低依次出现卷云→卷层云→高层云→雨层云。暖锋过境后气温升高、气压降低、天气转晴。" },
  { q: "下列关于准静止锋的叙述，正确的是？", options: ["冷暖空气势均力敌", "移动速度很快", "不会产生降水", "只发生在冬季"], answer: 0, explanation: "准静止锋是冷暖气团势均力敌、移动缓慢或停滞的锋面。准静止锋常带来持续阴雨天气。中国长江中下游地区的梅雨（6月）就是准静止锋（江淮准静止锋）形成的。" },
  { q: "台风是形成于热带洋面的强烈气旋，其特征是？", options: ["中心风力最大", "中心天气晴朗（眼）", "只影响陆地", "冬季最多"], answer: 1, explanation: "台风（热带气旋）中心有一个'台风眼'，因下沉气流而天气晴朗、风力微弱。但台风眼周围是最大风力和暴雨区。台风主要在夏秋季节影响沿海地区，带来狂风暴雨。" },
  { q: "下列关于厄尔尼诺现象的叙述，正确的是？", options: ["赤道东太平洋海水异常升温", "赤道东太平洋海水异常降温", "秘鲁沿海鱼类增多", "对全球气候无影响"], answer: 0, explanation: "厄尔尼诺现象是指赤道东太平洋海水异常升温的现象。正常年份秘鲁沿海寒流使下层冷水上涌，厄尔尼诺时暖水东流，冷水上涌减弱，影响全球气候，如秘鲁暴雨、东南亚干旱。" },
  { q: "下列关于拉尼娜现象的叙述，正确的是？", options: ["赤道东太平洋海水异常升温", "赤道东太平洋海水异常降温", "是厄尔尼诺的反位相", "对气候无影响"], answer: 1, explanation: "拉尼娜现象是指赤道东太平洋海水异常降温的现象，是厄尔尼诺的反位相。拉尼娜年信风增强，深层冷水上涌加强，秘鲁沿海鱼类增多。拉尼娜常导致东南亚多雨、美洲部分地区干旱。" },
  { q: "下列关于洋流对地理环境影响的叙述，正确的是？", options: ["暖流对沿岸降温减湿", "寒流对沿岸增温增湿", "洋流影响海洋生物分布", "洋流对气候无影响"], answer: 2, explanation: "洋流对沿岸气候有重要影响：暖流增温增湿（如北大西洋暖流使西欧温暖），寒流降温减湿（如秘鲁寒流使秘鲁沿海干燥）。洋流还影响海洋生物分布（渔场形成）、海洋航行和污染物扩散。" },
  { q: "下列关于水循环意义的叙述，不正确的是？", options: ["维持全球水量平衡", "促进水体不断更新", "加剧全球水危机", "调节气候和生态"], answer: 2, explanation: "水循环的意义包括：维持全球水的动态平衡、促进陆地水体不断更新、进行物质迁移和能量交换、调节气候和生态。水循环有助于缓解而非加剧水危机。水循环使陆地淡水资源得以更新。" },
  { q: "下列关于河流与等高线关系的叙述，正确的是？", options: ["河流总是与等高线平行", "河流流向与等高线弯曲方向相反", "河流流向与等高线弯曲方向相同", "河流流向与等高线无关"], answer: 1, explanation: "在地形图上，河流流向与等高线弯曲方向相反。等高线向高处弯曲处为河谷，河流向低处流。因为河流切割地表形成谷地，等高线向高处弯曲（V字形指向高处），河流则向低处流。" },
  { q: "下列关于潜水和承压水的叙述，正确的是？", options: ["潜水埋藏在第一个隔水层之上", "承压水埋藏在第一个隔水层之上", "潜水受气候影响大", "承压水水质差"], answer: 2, explanation: "潜水埋藏在第一个隔水层之上，直接接受大气降水补给，受气候影响大，水位变化大。承压水埋藏在两个隔水层之间，受气候影响小，水质好，水量稳定。潜水易受污染。" },
  { q: "下列关于板块学说的叙述，正确的是？", options: ["板块内部地壳稳定", "板块边界地壳活跃", "板块只做水平运动", "板块运动速度很快"], answer: 1, explanation: "板块构造学说认为板块边界（生长边界和消亡边界）地壳活动活跃，多火山地震。板块内部相对稳定。板块做水平运动为主，速度很慢（每年几厘米），但长期累积产生巨大变化。" },
  { q: "下列关于地震的叙述，正确的是？", options: ["震级越大破坏力越大", "烈度只与震级有关", "震源越深破坏越大", "震中距越大烈度越大"], answer: 0, explanation: "震级反映地震释放能量的大小，震级越大破坏力越大。烈度反映地震对地面影响和破坏程度，与震级、震源深度、震中距、地质条件、建筑结构等因素有关。浅源地震破坏力通常大于深源地震。" },
  { q: "下列关于火山分布的叙述，正确的是？", options: ["火山只分布在板块边界", "环太平洋火山带最集中", "火山分布与板块无关", "火山只分布在海洋中"], answer: 1, explanation: "火山主要分布在板块边界，特别是环太平洋火山带集中了全球大部分活火山。此外地中海-喜马拉雅火山带和东非裂谷带也有火山分布。大洋中脊（海底火山）也是重要火山带。" },
  { q: "下列属于外力作用的是？", options: ["岩浆活动", "变质作用", "风化作用", "地震"], answer: 2, explanation: "外力作用包括风化、侵蚀、搬运、沉积和固结成岩等过程，主要由太阳能驱动。内力作用包括岩浆活动、变质作用、地壳运动和地震等，由地球内能驱动。外力使地表趋于平坦，内力使地表趋于高低起伏。" },
  { q: "风化作用与侵蚀作用的区别是？", options: ["风化不移动岩石", "侵蚀不移动岩石", "风化只在沙漠", "侵蚀只在海洋"], answer: 0, explanation: "风化作用是指岩石在原地因温度变化、水、大气、生物等因素发生物理或化学破坏，不涉及物质移动。侵蚀作用则是在风化产物基础上，由流水、风力、冰川等外力对岩石进行破坏并搬运走。" },
  { q: "下列关于地貌与人类活动关系的叙述，正确的是？", options: ["山区不适合修建水库", "冲积平原适合发展农业", "沙漠地区适合发展工业", "高原适合发展渔业"], answer: 1, explanation: "冲积平原地势平坦、土壤肥沃、水源充足，适合发展农业，也是人口密集区。山区适合修建水库（有峡谷作坝址）和发展林业。高原适合发展畜牧业。沙漠地区生态脆弱，不宜大规模开发。" },
  { q: "下列关于自然带分布规律的叙述，正确的是？", options: ["纬度地带性从赤道向两极变化", "经度地带性从沿海向内陆变化", "垂直地带性随海拔变化", "以上都对"], answer: 3, explanation: "自然带分布有三大规律：纬度地带性（热量差异导致从赤道向两极更替）、经度地带性（水分差异导致从沿海向内陆更替）、垂直地带性（水热差异导致随海拔更替）。三者共同构成自然带分布格局。" },
  { q: "下列关于自然带垂直分布的叙述，正确的是？", options: ["纬度越低山地垂直自然带越多", "纬度越高山地垂直自然带越多", "海拔越高垂直自然带越少", "垂直自然带与纬度无关"], answer: 0, explanation: "山地垂直自然带谱的复杂程度与纬度和相对高度有关。纬度越低（基带为热带）、海拔越高，垂直自然带越多。如赤道附近的高山从山麓到山顶相当于从热带到极地的变化，自然带最丰富。" },
  { q: "下列关于陆地环境整体性的叙述，正确的是？", options: ["地理环境各要素相互联系", "各要素独立发展", "改变一个要素不影响其他", "各要素之间无联系"], answer: 0, explanation: "陆地环境整体性是指地理环境各要素（气候、水文、地貌、生物、土壤）相互联系、相互制约、相互渗透，构成一个有机整体。改变其中一个要素会引起其他要素甚至整个环境的变化。" },
  { q: "下列关于陆地环境地域分异的叙述，正确的是？", options: ["地域分异无规律可循", "地域分异是有规律的", "各地环境完全相同", "地域分异只与地形有关"], answer: 1, explanation: "陆地环境地域分异是有规律的，主要表现为纬度地带性（热量为基础）、经度地带性（水分为基础）和垂直地带性（水热条件随高度变化）。这些规律反映了自然地理环境的系统性。" },
  { q: "下列关于地理环境对人类活动影响的叙述，正确的是？", options: ["地理环境决定人类社会", "人类社会完全不受地理环境影响", "地理环境是人类发展的外部条件", "地理环境与人类活动无关"], answer: 2, explanation: "地理环境是人类社会发展的外部条件而非决定因素。地理环境影响人类的生产生活方式、聚落分布、交通线路等，但人类也能改造和适应环境。过分强调环境决定论或完全忽视环境影响都是不正确的。" },
  { q: "地球公转轨道面称为？", options: ["赤道面", "黄道面", "白道面", "地平面"], answer: 1, explanation: "地球公转轨道面称为黄道面。黄道面与赤道面的夹角即黄赤交角（约23.5°），这个夹角是导致四季更替的根本原因。太阳在一年中的视运动轨迹称为黄道，实际是地球公转的反映。" },

  // ========== 世界地理（101-200） ==========
  { q: "七大洲中面积最大的是？", options: ["亚洲", "非洲", "北美洲", "南极洲"], answer: 0, explanation: "亚洲是七大洲中面积最大的洲，面积约4400万平方千米，占全球陆地面积的29.4%。七大洲面积排序为亚洲>非洲>北美洲>南美洲>南极洲>欧洲>大洋洲。" },
  { q: "七大洲中面积最小的是？", options: ["大洋洲", "欧洲", "南极洲", "南美洲"], answer: 0, explanation: "大洋洲是七大洲中面积最小的洲，面积约897万平方千米，占全球陆地面积的6%。大洋洲包括澳大利亚大陆和太平洋上的众多岛屿。虽然面积最小，但拥有丰富的矿产资源和独特的动植物。" },
  { q: "四大洋中面积最大的是？", options: ["太平洋", "大西洋", "印度洋", "北冰洋"], answer: 0, explanation: "太平洋是四大洋中面积最大的洋，面积约1.65亿平方千米，占全球海洋面积的46%，超过陆地总面积。太平洋最深处马里亚纳海沟深11034米，是世界最深的海沟。" },
  { q: "四大洋中面积最小的是？", options: ["北冰洋", "印度洋", "大西洋", "太平洋"], answer: 0, explanation: "北冰洋是四大洋中面积最小的洋，面积约1475万平方千米，占全球海洋面积的4%。北冰洋位于北极圈内，大部分海面常年冰冻。近年来受全球变暖影响，北极海冰面积持续减少。" },
  { q: "美国的首都是？", options: ["华盛顿", "纽约", "洛杉矶", "芝加哥"], answer: 0, explanation: "美国的首都是华盛顿（华盛顿哥伦比亚特区，Washington D.C.）。华盛顿位于美国东海岸，是美国政治中心。纽约是美国最大城市和经济金融中心，但不是首都。华盛顿人口约70万，以政府机关和博物馆为主。" },
  { q: "英国的首都是？", options: ["伦敦", "曼彻斯特", "伯明翰", "爱丁堡"], answer: 0, explanation: "英国的首都是伦敦。伦敦位于英格兰东南部泰晤士河畔，是英国政治、经济、文化中心，也是世界重要的金融中心。伦敦是大不列颠及北爱尔兰联合王国首都，人口约900万。" },
  { q: "法国的首都是？", options: ["巴黎", "马赛", "里昂", "尼斯"], answer: 0, explanation: "法国的首都是巴黎。巴黎位于法国北部塞纳河畔，是法国政治、经济、文化中心。巴黎有埃菲尔铁塔、卢浮宫、巴黎圣母院等著名景点。巴黎是世界上最受欢迎的旅游城市之一。" },
  { q: "日本的首都是？", options: ["东京", "大阪", "京都", "名古屋"], answer: 0, explanation: "日本的首都是东京。东京位于日本本州岛东部，是日本政治、经济、文化中心。东京都市圈人口约3700万，是世界最大的都市圈。东京有皇居、浅草寺等著名景点。京都曾是日本古都（平安京）。" },
  { q: "俄罗斯的首都是？", options: ["莫斯科", "圣彼得堡", "海参崴", "喀山"], answer: 0, explanation: "俄罗斯的首都是莫斯科。莫斯科位于俄罗斯西部，是俄罗斯政治、经济、文化中心，也是欧洲人口最多的城市。莫斯科有克里姆林宫、红场等著名建筑。圣彼得堡曾是沙俄首都。" },
  { q: "印度的首都是？", options: ["新德里", "孟买", "加尔各答", "班加罗尔"], answer: 0, explanation: "印度的首都是新德里。新德里位于印度北部，是德里的一部分。新德里是印度政治中心，政府机关集中于此。孟买是印度最大城市和经济金融中心，被称为印度的'上海'。" },
  { q: "巴西的首都是？", options: ["巴西利亚", "圣保罗", "里约热内卢", "萨尔瓦多"], answer: 0, explanation: "巴西的首都是巴西利亚。巴西利亚位于巴西中部高原，1960年建成新首都。巴西利亚是联合国教科文组织世界遗产，以独特的城市规划闻名。里约热内卢曾为巴西首都（1763-1960年）。" },
  { q: "澳大利亚的首都是？", options: ["堪培拉", "悉尼", "墨尔本", "布里斯班"], answer: 0, explanation: "澳大利亚的首都是堪培拉。堪培拉位于悉尼和墨尔本之间，1913年建都。堪培拉是规划城市，人口约40万。悉尼是澳大利亚最大城市和经济中心，但不是首都。很多人误以为悉尼是澳大利亚首都。" },
  { q: "加拿大的首都是？", options: ["渥太华", "多伦多", "温哥华", "蒙特利尔"], answer: 0, explanation: "加拿大的首都是渥太华。渥太华位于安大略省东南部，是加拿大政治中心。多伦多是加拿大最大城市和经济金融中心，但不是首都。渥太华人口约100万，有议会山、里多运河等景点。" },
  { q: "德国的首都是？", options: ["柏林", "慕尼黑", "法兰克福", "汉堡"], answer: 0, explanation: "德国的首都是柏林。柏林位于德国东北部，是德国政治、文化中心。1990年德国统一后柏林再次成为首都。柏林有勃兰登堡门、柏林墙遗址等历史景点。法兰克福是德国金融中心，慕尼黑是巴伐利亚州首府。" },
  { q: "意大利的首都是？", options: ["罗马", "米兰", "佛罗伦萨", "威尼斯"], answer: 0, explanation: "意大利的首都是罗马。罗马位于意大利中部，是意大利政治、文化中心。罗马有古罗马斗兽场、万神殿等古迹，是西方文明重要发源地。梵蒂冈位于罗马城内。米兰是意大利经济中心。" },
  { q: "西班牙的首都是？", options: ["马德里", "巴塞罗那", "塞维利亚", "瓦伦西亚"], answer: 0, explanation: "西班牙的首都是马德里。马德里位于西班牙中部，是西班牙政治、经济、文化中心。马德里有皇宫、普拉多博物馆等。巴塞罗那是西班牙第二大城市，以高迪建筑闻名，但不是首都。" },
  { q: "韩国的首都是？", options: ["首尔", "釜山", "仁川", "济州"], answer: 0, explanation: "韩国的首都是首尔。首尔位于韩国西北部，是韩国政治、经济、文化中心。首尔都市圈人口约2500万，占韩国人口近一半。首尔有景福宫、青瓦台等。釜山是韩国第二大城市和最大港口。" },
  { q: "泰国的首都是？", options: ["曼谷", "清迈", "普吉", "芭提雅"], answer: 0, explanation: "泰国的首都是曼谷。曼谷位于泰国中部湄南河畔，是泰国政治、经济、文化中心。曼谷有大皇宫、玉佛寺等著名景点。曼谷都市圈人口超过1000万，是东南亚最大城市之一。" },
  { q: "新加坡是首都还是国家？", options: ["既是国家也是首都", "只是城市", "只是国家", "不是国家"], answer: 0, explanation: "新加坡既是一个国家也是一个城市，是典型的城邦国家。新加坡位于马来半岛南端，面积728平方千米，人口约570万。新加坡是重要的国际金融、航运和贸易中心。新加坡不设首都，整个国家即城市。" },
  { q: "埃及的首都是？", options: ["开罗", "亚历山大", "吉萨", "卢克索"], answer: 0, explanation: "埃及的首都是开罗。开罗位于尼罗河三角洲南端，是埃及政治、经济、文化中心。开罗附近有吉萨金字塔群和狮身人面像。开罗是非洲和中东最大城市之一，人口超过2000万。亚历山大是埃及第二大城市。" },
  { q: "南非有三个首都，分别是？", options: ["比勒陀利亚、开普敦、布隆方丹", "约翰内斯堡、德班", "开普敦、约翰内斯堡", "比勒陀利亚、约翰内斯堡"], answer: 0, explanation: "南非是世界上唯一有三个首都的国家：行政首都比勒陀利亚（总统府和政府机关）、立法首都开普敦（议会）、司法首都布隆方丹（最高法院）。约翰内斯堡是南非最大城市和经济中心，但不是首都。" },
  { q: "世界上最高的山脉是？", options: ["喜马拉雅山脉", "阿尔卑斯山脉", "安第斯山脉", "落基山脉"], answer: 0, explanation: "喜马拉雅山脉是世界上最高的山脉，平均海拔6000米以上。喜马拉雅山脉有10座海拔超过8000米的高峰，包括世界最高峰珠穆朗玛峰（8848.86米）。喜马拉雅山脉位于中国和尼泊尔、印度、不丹之间。" },
  { q: "世界上最长的山脉是？", options: ["安第斯山脉", "喜马拉雅山脉", "落基山脉", "阿尔卑斯山脉"], answer: 0, explanation: "安第斯山脉是世界上最长的山脉，全长约7000公里，纵贯南美洲西部。安第斯山脉平均海拔约4000米，最高峰阿空加瓜山海拔6962米。安第斯山脉是科迪勒拉山系的一部分。" },
  { q: "北美洲最长的山脉是？", options: ["落基山脉", "阿巴拉契亚山脉", "海岸山脉", "内华达山脉"], answer: 0, explanation: "落基山脉是北美洲最长的山脉，全长约4800公里，从加拿大不列颠哥伦比亚省延伸到美国新墨西哥州。落基山脉最高峰埃尔伯特山海拔4401米。落基山脉是北美大陆分水岭，也是科迪勒拉山系的一部分。" },
  { q: "世界上最长的河流是？", options: ["尼罗河", "亚马逊河", "长江", "密西西比河"], answer: 0, explanation: "尼罗河是世界上公认最长的河流，全长约6650公里。尼罗河发源于东非高原，流经布隆迪、卢旺达、坦桑尼亚、乌干达、南苏丹和苏丹，在埃及注入地中海。但也有研究认为亚马逊河更长。" },
  { q: "世界上流量最大的河流是？", options: ["亚马逊河", "尼罗河", "长江", "密西西比河"], answer: 0, explanation: "亚马逊河是世界上流量最大的河流，平均流量约21万立方米/秒，占全球河流入海总量的20%。亚马逊河流域面积约705万平方千米，是世界上流域面积最大的河流。亚马逊河发源于安第斯山，注入大西洋。" },
  { q: "世界上流域面积最大的河流是？", options: ["亚马逊河", "尼罗河", "密西西比河", "刚果河"], answer: 0, explanation: "亚马逊河流域面积约705万平方千米，是世界上流域面积最大的河流，覆盖南美洲约40%的面积。亚马逊河流经巴西、秘鲁、哥伦比亚等国。亚马逊河流域拥有世界最大的热带雨林，被称为'地球之肺'。" },
  { q: "密西西比河注入哪个海洋？", options: ["墨西哥湾", "大西洋", "太平洋", "加勒比海"], answer: 0, explanation: "密西西比河注入墨西哥湾。密西西比河是美国最大的河流，全长约6275公里（含密苏里河）。密西西比河流域面积约322万平方千米，覆盖美国约40%的国土。密西西比河是美国重要的内河航运通道。" },
  { q: "伏尔加河是哪个洲最长的河流？", options: ["欧洲", "亚洲", "非洲", "北美洲"], answer: 0, explanation: "伏尔加河是欧洲最长的河流，全长约3530公里。伏尔加河发源于东欧平原，在里海注入，是世界上最长的内流河。伏尔加河是俄罗斯母亲河，流域覆盖俄罗斯欧洲部分约三分之一面积。" },
  { q: "多瑙河流经多少个国家？", options: ["10个", "7个", "5个", "12个"], answer: 0, explanation: "多瑙河流经10个国家，是世界上流经国家最多的河流。多瑙河发源于德国黑林山，流经德国、奥地利、斯洛伐克、匈牙利、克罗地亚、塞尔维亚、罗马尼亚、保加利亚、摩尔多瓦和乌克兰，注入黑海。" },
  { q: "马六甲海峡连接哪两个海洋？", options: ["太平洋和印度洋", "太平洋和大西洋", "大西洋和印度洋", "北冰洋和太平洋"], answer: 0, explanation: "马六甲海峡连接太平洋（南海）和印度洋（安达曼海），是亚洲最重要的海上通道。马六甲海峡位于马来半岛和苏门答腊岛之间，最窄处约37公里。每年有数万艘船只通过，被称为'海上十字路口'。" },
  { q: "霍尔木兹海峡连接哪两个海域？", options: ["波斯湾和阿曼湾", "红海和地中海", "黑海和地中海", "波斯湾和红海"], answer: 0, explanation: "霍尔木兹海峡连接波斯湾和阿曼湾（阿拉伯海/印度洋），是波斯湾石油输出的唯一海上通道。霍尔木兹海峡被称为'世界油阀'，全球约三分之一的海运石油经此运输，战略地位极为重要。" },
  { q: "直布罗陀海峡连接哪两个海洋？", options: ["地中海和大西洋", "地中海和红海", "黑海和地中海", "大西洋和北海"], answer: 0, explanation: "直布罗陀海峡连接地中海和大西洋，位于欧洲伊比利亚半岛和非洲西北部之间。直布罗陀海峡最窄处约14公里，是地中海通往大西洋的唯一通道，战略地位十分重要。" },
  { q: "英吉利海峡连接哪两个海域？", options: ["北海和大西洋", "波罗的海和北海", "大西洋和地中海", "北海和地中海"], answer: 0, explanation: "英吉利海峡（英法海峡）连接北海和大西洋，位于英国和法国之间。英吉利海峡最窄处约34公里，是多佛尔海峡。英法海底隧道穿越此海峡。英吉利海峡是世界最繁忙的航运通道之一。" },
  { q: "土耳其海峡连接哪两个海域？", options: ["黑海和地中海", "地中海和红海", "黑海和里海", "地中海和大西洋"], answer: 0, explanation: "土耳其海峡（黑海海峡）连接黑海和地中海（爱琴海），由博斯普鲁斯海峡和达达尼尔海峡以及两者之间的马尔马拉海组成。土耳其海峡是黑海沿岸国家通往地中海的唯一通道，战略地位十分重要。" },
  { q: "苏伊士运河连接哪两个海洋？", options: ["地中海和红海", "地中海和大西洋", "红海和阿拉伯海", "地中海和黑海"], answer: 0, explanation: "苏伊士运河连接地中海和红海，全长约193公里。苏伊士运河1869年通航，是亚洲和非洲的分界线。苏伊士运河使欧洲到亚洲的航程比绕好望角缩短约7000公里，是世界最重要的航运通道之一。" },
  { q: "巴拿马运河连接哪两个海洋？", options: ["太平洋和大西洋", "太平洋和印度洋", "大西洋和印度洋", "太平洋和北冰洋"], answer: 0, explanation: "巴拿马运河连接太平洋和大西洋，全长约82公里。巴拿马运河1914年通航，是南美洲和北美洲的分界线。巴拿马运河使纽约到旧金山的航程比绕合恩角缩短约14000公里，是世界最重要的航运通道之一。" },
  { q: "巴拿马运河于哪一年通航？", options: ["1914年", "1900年", "1920年", "1930年"], answer: 0, explanation: "巴拿马运河于1914年8月15日通航。巴拿马运河由美国修建，1999年美国将运河交还巴拿马。巴拿马运河2016年扩建完成，可通行更大的'新巴拿马型'船只。巴拿马运河是世界工程奇迹之一。" },
  { q: "苏伊士运河于哪一年通航？", options: ["1869年", "1850年", "1880年", "1900年"], answer: 0, explanation: "苏伊士运河于1869年11月17日通航。苏伊士运河由法国工程师主持修建，历时10年。苏伊士运河是亚洲与非洲的分界线，使欧洲到亚洲的航程大大缩短。2021年'长赐号'货轮搁浅导致运河堵塞数日。" },
  { q: "好望角位于哪个大洲？", options: ["非洲", "南美洲", "澳大利亚", "亚洲"], answer: 0, explanation: "好望角位于非洲南端南非共和国。好望角是大西洋和印度洋的交汇处。1488年葡萄牙航海家迪亚士首次到达好望角。苏伊士运河开通前，好望角是欧洲到亚洲的主要航道。好望角风浪大，航海危险。" },
  { q: "世界最大的沙漠是？", options: ["撒哈拉沙漠", "塔克拉玛干沙漠", "戈壁沙漠", "阿拉伯沙漠"], answer: 0, explanation: "撒哈拉沙漠是世界上最大的热带沙漠，面积约906万平方千米，位于非洲北部。撒哈拉沙漠横跨11个国家，是世界上仅次于南极洲的第二大荒漠。撒哈拉沙漠气候极端干旱，但地下蕴藏丰富的石油和天然气。" },
  { q: "世界最大的热带雨林位于？", options: ["亚马逊河流域", "刚果盆地", "东南亚群岛", "中美洲"], answer: 0, explanation: "世界最大的热带雨林位于南美洲亚马逊河流域，面积约500万平方千米，被称为'地球之肺'。亚马逊雨林占全球热带雨林面积的一半以上，生物多样性极为丰富。亚马逊雨林对全球气候调节有重要作用。" },
  { q: "世界最大的高原是？", options: ["巴西高原", "青藏高原", "蒙古高原", "伊朗高原"], answer: 0, explanation: "巴西高原是世界上面积最大的高原，面积约500万平方千米，位于南美洲巴西中部。巴西高原地势平坦，海拔约600-900米。巴西高原矿产资源丰富，是巴西重要的农业和矿业区。青藏高原是世界海拔最高的高原。" },
  { q: "世界最大的平原是？", options: ["亚马逊平原", "东欧平原", "西西伯利亚平原", "华北平原"], answer: 0, explanation: "亚马逊平原是世界上面积最大的平原，面积约560万平方千米，位于南美洲亚马逊河流域。亚马逊平原地势低平，海拔一般不超过200米。亚马逊平原大部分被热带雨林覆盖，生物多样性极为丰富。" },
  { q: "尼罗河注入哪个海？", options: ["地中海", "红海", "阿拉伯海", "大西洋"], answer: 0, explanation: "尼罗河注入地中海。尼罗河发源于东非高原（布隆迪），流经布隆迪、卢旺达、坦桑尼亚、乌干达、南苏丹和苏丹，在埃及开罗附近形成三角洲注入地中海。尼罗河三角洲是埃及人口和农业最集中的地区。" },
  { q: "亚马逊河注入哪个海洋？", options: ["大西洋", "太平洋", "加勒比海", "墨西哥湾"], answer: 0, explanation: "亚马逊河注入大西洋。亚马逊河发源于秘鲁安第斯山，流经秘鲁、哥伦比亚、巴西等国，在巴西东部注入大西洋。亚马逊河全长约6400公里，是世界上流量最大、流域面积最大的河流。" },
  { q: "伏尔加河注入哪个湖泊或海洋？", options: ["里海", "黑海", "波罗的海", "咸海"], answer: 0, explanation: "伏尔加河注入里海。伏尔加河发源于东欧平原瓦尔代丘陵，全长约3530公里，是欧洲最长的河流。伏尔加河是世界上最长的内流河，最终流入里海（世界最大的内陆湖）。伏尔加河是俄罗斯'母亲河'。" },
  { q: "世界最大的内陆湖泊是？", options: ["里海", "咸海", "贝加尔湖", "青海湖"], answer: 0, explanation: "里海是世界最大的内陆湖泊（也是最大的咸水湖），面积约37万平方千米。里海位于亚欧大陆交界处，被俄罗斯、哈萨克斯坦、土库曼斯坦、伊朗和阿塞拜疆环绕。里海蕴藏丰富的石油和天然气资源。" },
  { q: "世界最深的湖泊是？", options: ["贝加尔湖", "里海", "苏必利尔湖", "坦噶尼喀湖"], answer: 0, explanation: "贝加尔湖是世界最深的湖泊，最深处达1642米。贝加尔湖位于俄罗斯西伯利亚南部，面积约31500平方千米。贝加尔湖是世界上最古老的淡水湖（约2500万年），湖水极为清澈，有大量特有物种。" },
  { q: "世界最大的淡水湖（按面积）是？", options: ["苏必利尔湖", "贝加尔湖", "维多利亚湖", "休伦湖"], answer: 0, explanation: "苏必利尔湖是世界上面积最大的淡水湖，面积约82100平方千米。苏必利尔湖是北美五大湖之一，位于美国和加拿大交界处。苏必利尔湖最深处406米。贝加尔湖是世界最深的湖，也是蓄水量最大的淡水湖。" },
  { q: "北美五大湖中面积最大的是？", options: ["苏必利尔湖", "休伦湖", "密歇根湖", "安大略湖"], answer: 0, explanation: "苏必利尔湖是北美五大湖中面积最大的，面积约82100平方千米，也是世界最大的淡水湖。五大湖（苏必利尔、密歇根、休伦、伊利、安大略）总面积约244106平方千米，是世界上最大的淡水湖群。" },
  { q: "非洲最大的湖泊是？", options: ["维多利亚湖", "坦噶尼喀湖", "马拉维湖", "图尔卡纳湖"], answer: 0, explanation: "维多利亚湖是非洲最大的湖泊，面积约68870平方千米，也是世界第二大淡水湖。维多利亚湖位于东非，被乌干达、坦桑尼亚和肯尼亚环绕。维多利亚湖是尼罗河的重要源头之一。" },
  { q: "非洲最深的湖泊是？", options: ["坦噶尼喀湖", "维多利亚湖", "马拉维湖", "图尔卡纳湖"], answer: 0, explanation: "坦噶尼喀湖是非洲最深的湖泊，最深处1470米，也是世界第二深湖（仅次于贝加尔湖）。坦噶尼喀湖位于东非大裂谷西部，被布隆迪、坦桑尼亚、赞比亚和刚果民主共和国环绕。坦噶尼喀湖长约673公里，是世界最长的湖。" },
  { q: "世界最大的半岛是？", options: ["阿拉伯半岛", "印度半岛", "中南半岛", "朝鲜半岛"], answer: 0, explanation: "阿拉伯半岛是世界上最大的半岛，面积约322万平方千米。阿拉伯半岛位于亚洲西南部，包括沙特阿拉伯、也门、阿曼、阿联酋、卡塔尔、科威特和巴林等国。阿拉伯半岛蕴藏世界最丰富的石油资源。" },
  { q: "世界最大的岛屿是？", options: ["格陵兰岛", "新几内亚岛", "加里曼丹岛", "马达加斯加岛"], answer: 0, explanation: "格陵兰岛是世界上最大的岛屿，面积约216万平方千米。格陵兰岛位于北美洲东北部，属丹麦自治领。格陵兰岛大部分位于北极圈内，约80%的土地被冰盖覆盖。新几内亚岛（约78.5万）是第二大岛。" },
  { q: "世界第二大的岛屿是？", options: ["新几内亚岛", "格陵兰岛", "加里曼丹岛", "马达加斯加岛"], answer: 0, explanation: "新几内亚岛（伊里安岛）是世界第二大岛，面积约78.5万平方千米。新几内亚岛位于太平洋西南部，被印度尼西亚和巴布亚新几内亚分治。新几内亚岛有热带雨林和高山，查亚峰海拔4884米。" },
  { q: "世界第三大的岛屿是？", options: ["加里曼丹岛", "格陵兰岛", "新几内亚岛", "马达加斯加岛"], answer: 0, explanation: "加里曼丹岛（婆罗洲）是世界第三大岛，面积约74.3万平方千米。加里曼丹岛位于东南亚，被印度尼西亚、马来西亚和文莱分治。加里曼丹岛有热带雨林，是生物多样性最丰富的地区之一。" },
  { q: "世界最大的群岛是？", options: ["马来群岛", "日本群岛", "不列颠群岛", "菲律宾群岛"], answer: 0, explanation: "马来群岛是世界上最大的群岛，约由2万个岛屿组成，总面积约247万平方千米。马来群岛包括印度尼西亚、菲律宾、马来西亚东部等。马来群岛地处赤道附近，气候热带雨林，地震火山活动频繁。" },
  { q: "世界最大的三角洲是？", options: ["恒河三角洲", "尼罗河三角洲", "亚马逊三角洲", "长江三角洲"], answer: 0, explanation: "恒河三角洲（恒河-布拉马普特拉河三角洲）是世界上最大的三角洲，面积约10.6万平方千米。恒河三角洲位于孟加拉国和印度交界处，是人口极度密集的地区。恒河三角洲地势低平，易受风暴潮和洪水侵袭。" },
  { q: "世界最热的地方记录在哪个地区？", options: ["加利福尼亚死亡谷", "撒哈拉沙漠", "利比亚", "伊朗卢特沙漠"], answer: 0, explanation: "世界上官方认可的最高气温记录是加利福尼亚州死亡谷的56.7°C（1913年）。也有记录显示伊朗卢特沙漠地表温度高达70°C以上。利比亚的阿济济耶曾记录58°C但被世界气象组织废止。死亡谷是北美最热最干燥的地区。" },
  { q: "世界最冷的地方是？", options: ["南极洲东方站", "西伯利亚奥伊米亚康", "北极", "格陵兰岛"], answer: 0, explanation: "世界最低气温记录在南极洲东方站，为-89.2°C（1983年）。也有卫星数据显示南极洲东部某处地表温度低至-98°C。北半球最低温记录在西伯利亚奥伊米亚康，约-67.8°C，是北半球最冷的人类定居点。" },
  { q: "世界降水最多的地方是？", options: ["印度乞拉朋齐", "夏威夷怀厄莱阿莱", "哥伦比亚略约", "台湾火烧寮"], answer: 0, explanation: "印度东北部乞拉朋齐是世界上年降水量最多的地方之一，年均降水量超过11000毫米，被称为'世界雨极'。乞拉朋齐位于喜马拉雅山南麓迎风坡，夏季受西南季风影响降水极为丰沛。夏威夷怀厄莱阿莱也很高。" },
  { q: "世界人口最多的国家是？", options: ["印度", "中国", "美国", "印度尼西亚"], answer: 0, explanation: "2023年印度人口超过中国，成为世界人口最多的国家。印度人口约14.3亿，中国约14.1亿。美国人口约3.3亿居第三。印度尼西亚人口约2.7亿居第四。中国曾长期是世界人口最多的国家，直到2023年被印度超越。" },
  { q: "世界面积最大的国家是？", options: ["俄罗斯", "加拿大", "中国", "美国"], answer: 0, explanation: "俄罗斯是世界上面积最大的国家，面积约1709万平方千米，横跨欧亚两大洲。加拿大面积998万平方千米居第二，中国960万平方千米居第三，美国937万平方千米居第四。俄罗斯面积约为月球表面积的近一半。" },
  { q: "世界面积最小的国家是？", options: ["梵蒂冈", "摩纳哥", "圣马力诺", "瑙鲁"], answer: 0, explanation: "梵蒂冈是世界上面积最小的国家，仅约0.44平方千米。梵蒂冈位于意大利罗马城内，是天主教教廷所在地。梵蒂冈人口约800人，也是世界上人口最少的国家。梵蒂冈是联合国观察员国。" },
  { q: "世界上跨经度最多的国家是？", options: ["俄罗斯", "加拿大", "美国", "中国"], answer: 0, explanation: "俄罗斯是世界上跨经度最多的国家，从西经19°到东经169°，跨约171个经度，几乎占地球半圈。俄罗斯横跨欧亚两大洲，有11个时区。俄罗斯从波罗的海延伸到太平洋，东西距离约9000公里。" },
  { q: "世界上跨纬度最多的国家是？", options: ["智利", "俄罗斯", "巴西", "中国"], answer: 0, explanation: "智利是世界上跨纬度最多的国家之一，从北纬17°到南纬56°，南北跨约39个纬度（约4300公里），但东西宽度平均仅约180公里。智利呈狭长形，是世界上地形最狭长的国家。俄罗斯、巴西和中国也跨纬度较多。" },
  { q: "世界上最大的内陆国是？", options: ["哈萨克斯坦", "蒙古", "乍得", "尼日尔"], answer: 0, explanation: "哈萨克斯坦是世界上面积最大的内陆国，面积约272万平方千米。哈萨克斯坦位于中亚，西濒里海。蒙古是第二大内陆国，面积约156万平方千米。内陆国没有出海口，对外贸易受地理限制。" },
  { q: "非洲最长的河流是？", options: ["尼罗河", "刚果河", "尼日尔河", "赞比西河"], answer: 0, explanation: "尼罗河是非洲最长的河流，全长约6650公里，也是世界最长河流。尼罗河发源于东非高原，流经布隆迪、卢旺达、坦桑尼亚、乌干达、南苏丹、苏丹和埃及，在埃及注入地中海。尼罗河三角洲是埃及人口和农业集中地。" },
  { q: "欧洲最长的河流是？", options: ["伏尔加河", "多瑙河", "莱茵河", "第聂伯河"], answer: 0, explanation: "伏尔加河是欧洲最长的河流，全长约3530公里。伏尔加河发源于东欧平原，流入里海，是世界上最长的内流河。伏尔加河是俄罗斯'母亲河'，流域覆盖俄罗斯欧洲部分约三分之一面积。多瑙河是欧洲第二长河（约2850公里）。" },
  { q: "北美洲最长的河流是？", options: ["密西西比河", "密苏里河", "科罗拉多河", "哥伦比亚河"], answer: 0, explanation: "密西西比河是北美洲最长的河流（含密苏里河全长约6275公里）。密西西比河发源于美国明尼苏达州，流经美国中部，在路易斯安那州新奥尔良附近注入墨西哥湾。密西西比河流域面积约322万平方千米。" },
  { q: "南美洲最长的河流是？", options: ["亚马逊河", "巴拉那河", "奥里诺科河", "乌拉圭河"], answer: 0, explanation: "亚马逊河是南美洲最长的河流，全长约6400公里。亚马逊河发源于秘鲁安第斯山，流经秘鲁、哥伦比亚、巴西等国，在巴西东部注入大西洋。亚马逊河是世界上流量最大、流域面积最大的河流。" },
  { q: "世界上最长的内流河是？", options: ["伏尔加河", "塔里木河", "阿姆河", "锡尔河"], answer: 0, explanation: "伏尔加河是世界上最长的内流河，全长约3530公里。伏尔加河发源于东欧平原，流入里海（内陆湖）。伏尔加河是欧洲最长的河流，也是俄罗斯'母亲河'。中国塔里木河是世界第二长内流河（约2179公里）。" },
  { q: "世界上最大的峡谷是？", options: ["雅鲁藏布大峡谷", "科罗拉多大峡谷", "东非大裂谷", "长江三峡"], answer: 0, explanation: "雅鲁藏布大峡谷是世界上最大的峡谷，最深处6009米，全长504.6公里。科罗拉多大峡谷是美国最著名的峡谷，长约446公里，最深处约1857米。东非大裂谷是世界上最长的裂谷，但不是峡谷。" },
  { q: "科罗拉多大峡谷位于哪个国家？", options: ["美国", "墨西哥", "巴西", "阿根廷"], answer: 0, explanation: "科罗拉多大峡谷位于美国亚利桑那州。科罗拉多大峡谷由科罗拉多河经数百万年侵蚀形成，长约446公里，最深处约1857米，最宽处约29公里。科罗拉多大峡谷是世界自然遗产，也是美国最著名的国家公园之一。" },
  { q: "东非大裂谷的长度约为？", options: ["约6400公里", "约3000公里", "约1000公里", "约5000公里"], answer: 0, explanation: "东非大裂谷全长约6400公里，是世界上最长的裂谷带。东非大裂谷北起约旦的死海，南至莫桑比克，纵贯东非高原。东非大裂谷由非洲板块张裂运动形成，被称为'地球的伤疤'。裂谷中有众多湖泊和火山。" },
  { q: "死海是世界上最低的湖泊，海拔约为？", options: ["-430米", "-154米", "-300米", "-500米"], answer: 0, explanation: "死海湖面海拔约-430米（逐年下降中），是世界上最低的湖泊。死海位于以色列、约旦和巴勒斯坦交界处，属于东非大裂谷的一部分。死海水含盐量约34%，是一般海水的9.6倍，人可以浮在水面。" },
  { q: "里海是世界上最大的内陆湖泊，面积约？", options: ["37万平方千米", "20万平方千米", "50万平方千米", "15万平方千米"], answer: 0, explanation: "里海面积约37万平方千米，是世界上最大的内陆湖泊（也是最大的咸水湖）。里海位于亚欧大陆交界处，被俄罗斯、哈萨克斯坦、土库曼斯坦、伊朗和阿塞拜疆环绕。里海蕴藏丰富的石油和天然气。" },
  { q: "贝加尔湖是世界最深的湖泊，最深处约为？", options: ["1642米", "1000米", "2000米", "800米"], answer: 0, explanation: "贝加尔湖最深处1642米，是世界最深的湖泊。贝加尔湖位于俄罗斯西伯利亚南部，面积约31500平方千米。贝加尔湖是世界上最古老的淡水湖（约2500万年），也是蓄水量最大的淡水湖（约占全球地表淡水20%）。" },
  { q: "苏必利尔湖是世界上面积最大的淡水湖，面积约？", options: ["82100平方千米", "58000平方千米", "31500平方千米", "68870平方千米"], answer: 0, explanation: "苏必利尔湖面积约82100平方千米，是世界上面积最大的淡水湖。苏必利尔湖是北美五大湖之一，位于美国和加拿大交界处。苏必利尔湖最深处406米，是北美五大湖中最深、面积最大的湖泊。" },
  { q: "维多利亚湖是非洲最大的湖泊，面积约？", options: ["68870平方千米", "32000平方千米", "50000平方千米", "40000平方千米"], answer: 0, explanation: "维多利亚湖面积约68870平方千米，是非洲最大的湖泊，也是世界第二大淡水湖。维多利亚湖位于东非，被乌干达、坦桑尼亚和肯尼亚环绕。维多利亚湖是尼罗河的重要源头之一。英国探险家斯皮克'发现'了该湖。" },
  { q: "俄罗斯横跨哪两大洲？", options: ["欧洲和亚洲", "欧洲和北美洲", "亚洲和北美洲", "欧洲和非洲"], answer: 0, explanation: "俄罗斯横跨欧洲和亚洲两大洲。乌拉尔山是欧亚分界线，以西为欧洲部分，以东为亚洲部分（西伯利亚）。俄罗斯总面积约1709万平方千米，其中亚洲部分约占75%，但人口和政治经济重心在欧洲部分。" },
  { q: "土耳其横跨哪两大洲？", options: ["欧洲和亚洲", "欧洲和非洲", "亚洲和非洲", "欧洲和北美洲"], answer: 0, explanation: "土耳其横跨欧洲和亚洲两大洲。土耳其的伊斯坦布尔（君士坦丁堡）是世界上唯一跨两大洲的城市。博斯普鲁斯海峡和土耳其海峡是欧亚分界线。土耳其大部分国土在亚洲小亚细亚半岛，小部分在欧洲巴尔干半岛。" },
  { q: "巴拿马横跨哪两大洲？", options: ["北美洲和南美洲", "北美洲和欧洲", "南美洲和南极洲", "北美洲和亚洲"], answer: 0, explanation: "巴拿马横跨北美洲和南美洲。巴拿马运河是南美洲和北美洲的分界线。巴拿马运河连接太平洋和大西洋，是世界最重要的航运通道之一。巴拿马首都巴拿马城位于运河太平洋一侧。" },
  { q: "埃及横跨哪两大洲？", options: ["非洲和亚洲", "非洲和欧洲", "亚洲和欧洲", "非洲和南美洲"], answer: 0, explanation: "埃及横跨非洲和亚洲两大洲。埃及大部分国土在非洲东北部，西奈半岛位于亚洲。苏伊士运河是亚非分界线，也是埃及亚洲部分和非洲部分的分界线。西奈半岛有西奈山，是犹太教、基督教和伊斯兰教圣地。" },
  { q: "世界上海岸线最长的国家是？", options: ["加拿大", "俄罗斯", "澳大利亚", "印度尼西亚"], answer: 0, explanation: "加拿大是世界上海岸线最长的国家，海岸线总长约20.2万公里。加拿大东临大西洋，西临太平洋，北临北冰洋，海岸线极为漫长曲折。印度尼西亚海岸线也很长（约9.5万公里），是世界第二大岛国。" },
  { q: "世界上最大的群岛国家是？", options: ["印度尼西亚", "菲律宾", "日本", "英国"], answer: 0, explanation: "印度尼西亚是世界上最大的群岛国家，由约1.7万个岛屿组成，面积约191万平方千米。印度尼西亚人口约2.7亿，是世界第四大人口国。印度尼西亚横跨赤道，地处太平洋'火环'上，地震火山活动频繁。" },
  { q: "沙特阿拉伯的首都是？", options: ["利雅得", "吉达", "麦加", "麦地那"], answer: 0, explanation: "沙特阿拉伯的首都是利雅得。利雅得位于沙特阿拉伯中部，是沙特政治中心。麦加和麦地那是伊斯兰教两大圣城，但不是首都。吉达是沙特最大港口和经济中心。沙特阿拉伯是世界最大石油出口国之一。" },
  { q: "阿联酋的首都是？", options: ["阿布扎比", "迪拜", "沙迦", "阿莱因"], answer: 0, explanation: "阿拉伯联合酋长国的首都是阿布扎比。阿布扎比是阿联酋最大的酋长国。迪拜是阿联酋最知名的城市和经济中心，以哈利法塔（世界最高建筑）等闻名，但不是首都。阿布扎比也是阿联酋石油资源最丰富的酋长国。" },
  { q: "土耳其的首都是？", options: ["安卡拉", "伊斯坦布尔", "伊兹密尔", "布尔萨"], answer: 0, explanation: "土耳其的首都是安卡拉。安卡拉位于土耳其中部，是土耳其政治中心。伊斯坦布尔（原名君士坦丁堡）是土耳其最大城市和经济文化中心，横跨欧亚两大洲，曾是东罗马帝国和奥斯曼帝国首都，但不是现代土耳其首都。" },
  { q: "瑞士的首都是？", options: ["伯尔尼", "苏黎世", "日内瓦", "巴塞尔"], answer: 0, explanation: "瑞士的首都是伯尔尼。伯尔尼位于瑞士中部，是瑞士政治中心。苏黎世是瑞士最大城市和经济金融中心，日内瓦是国际组织云集的城市（联合国欧洲总部等），但都不是首都。瑞士是联邦制国家。" },
  { q: "荷兰的首都是？", options: ["阿姆斯特丹", "海牙", "鹿特丹", "乌特勒支"], answer: 0, explanation: "荷兰的首都是阿姆斯特丹。阿姆斯特丹是荷兰最大城市和宪法规定的首都。但荷兰政府机关和议会位于海牙（Den Haag），海牙也是国际法院所在地。鹿特丹是欧洲最大港口。荷兰是君主立宪制国家。" },
  { q: "新西兰的首都是？", options: ["惠灵顿", "奥克兰", "基督城", "汉密尔顿"], answer: 0, explanation: "新西兰的首都是惠灵顿。惠灵顿位于新西兰北岛南端，是新西兰政治中心。奥克兰是新西兰最大城市和经济中心，但不是首都。惠灵顿地处库克海峡，风大，被称为'风城'。惠灵顿是南半球最南端的首都。" },
  { q: "阿根廷的首都是？", options: ["布宜诺斯艾利斯", "罗萨里奥", "门多萨", "科尔多瓦"], answer: 0, explanation: "阿根廷的首都是布宜诺斯艾利斯。布宜诺斯艾利斯位于拉普拉塔河畔，是阿根廷政治、经济、文化中心，也是南美洲最大城市之一。布宜诺斯艾利斯有博卡区、探戈舞等文化特色。布宜诺斯艾利斯是南半球最大都市之一。" },
  { q: "智利的首都是？", options: ["圣地亚哥", "瓦尔帕莱索", "康塞普西翁", "蒙特港"], answer: 0, explanation: "智利的首都是圣地亚哥。圣地亚哥位于智利中部，是智利政治、经济、文化中心。智利是世界上地形最狭长的国家，南北长约4300公里，东西平均宽约180公里。瓦尔帕莱索是智利主要港口城市。" },
  { q: "秘鲁的首都是？", options: ["利马", "库斯科", "阿雷基帕", "特鲁希略"], answer: 0, explanation: "秘鲁的首都是利马。利马位于秘鲁太平洋沿岸，是秘鲁政治、经济、文化中心。库斯科曾是印加帝国首都，是世界遗产城市。利马气候温和干燥，被称为'无雨之城'。利马是南美洲太平洋沿岸最大城市之一。" },
  { q: "墨西哥的首都是？", options: ["墨西哥城", "瓜达拉哈拉", "蒙特雷", "普埃布拉"], answer: 0, explanation: "墨西哥的首都是墨西哥城。墨西哥城位于墨西哥中部高原，海拔约2240米，是墨西哥政治、经济、文化中心。墨西哥城人口约900万，大都市圈人口超过2100万，是世界最大都市圈之一。墨西哥城建在古阿兹特克城遗址上。" },
  { q: "伊朗的首都是？", options: ["德黑兰", "伊斯法罕", "设拉子", "马什哈德"], answer: 0, explanation: "伊朗的首都是德黑兰。德黑兰位于伊朗北部厄尔布尔士山南麓，是伊朗政治、经济、文化中心。德黑兰人口约850万，是西亚最大城市之一。伊斯法罕和设拉子是伊朗历史名城。德黑兰是伊朗最大的城市。" },
  { q: "伊拉克的首都是？", options: ["巴格达", "巴士拉", "摩苏尔", "纳杰夫"], answer: 0, explanation: "伊拉克的首都是巴格达。巴格达位于伊拉克中部底格里斯河畔，是伊拉克政治、经济、文化中心。巴格达建于762年，曾是阿拔斯王朝首都，是阿拉伯帝国鼎盛时期的政治文化中心，也是《一千零一夜》的故事发生地。" },
  { q: "伊斯兰教第一圣城麦加位于哪个国家？", options: ["沙特阿拉伯", "也门", "约旦", "埃及"], answer: 0, explanation: "伊斯兰教第一圣城麦加位于沙特阿拉伯。麦加是伊斯兰教先知穆罕默德的诞生地，有禁寺和克尔白（天房）。每年数百万穆斯林前往麦加朝觐（哈吉），是伊斯兰教五功之一。非穆斯林不得进入麦加。" },
  { q: "耶路撒冷是哪三大宗教的圣地？", options: ["犹太教、基督教、伊斯兰教", "佛教、犹太教、基督教", "印度教、基督教、伊斯兰教", "犹太教、基督教、巴哈伊教"], answer: 0, explanation: "耶路撒冷是犹太教、基督教和伊斯兰教三大一神教的圣地。犹太教有圣殿山（西墙/哭墙），基督教有圣墓教堂，伊斯兰教有圆顶清真寺和阿克萨清真寺。耶路撒冷是世界文化遗产，也是巴以冲突的核心。" },
  { q: "梵蒂冈是哪个宗教的中心？", options: ["天主教", "东正教", "新教", "伊斯兰教"], answer: 0, explanation: "梵蒂冈是天主教会的中心，教宗（教皇）驻地。梵蒂冈位于意大利罗马城内，面积0.44平方千米，是世界上面积最小、人口最少的国家。梵蒂冈有圣彼得大教堂、西斯廷礼拜堂等。梵蒂冈是联合国观察员国。" },
  { q: "世界上海拔最高的铁路是？", options: ["青藏铁路", "西伯利亚铁路", "安第斯铁路", "阿尔卑斯铁路"], answer: 0, explanation: "青藏铁路是世界海拔最高的铁路，最高点唐古拉山口海拔5072米。青藏铁路全长1956公里，2006年全线通车。青藏铁路攻克了多年冻土、高寒缺氧、生态脆弱三大世界难题。西伯利亚铁路是世界最长铁路（9289公里）。" },
  { q: "世界上最长的铁路是？", options: ["西伯利亚铁路", "青藏铁路", "京广铁路", "加拿大太平洋铁路"], answer: 0, explanation: "西伯利亚铁路（西伯利亚大铁路）是世界上最长的铁路，全长约9289公里。西伯利亚铁路从莫斯科到海参崴，连接欧亚两大洲。1891年开工，1916年全线通车。西伯利亚铁路是世界上最重要的陆路通道之一。" },
  { q: "世界上最长的海底隧道是？", options: ["英法海底隧道", "日本青函隧道", "港珠澳大桥沉管隧道", "瑞士圣哥达基线隧道"], answer: 0, explanation: "英法海底隧道（英吉利海峡隧道）全长约50公里，其中海底段约38公里，是世界上最长的海底隧道。1994年通车，连接英国福克斯通和法国加来。日本青函隧道全长53.85公里，但海底段约23.3公里。港珠澳大桥沉管隧道全长6.7公里。" },
  { q: "世界上最长的陆地隧道是？", options: ["瑞士圣哥达基线隧道", "日本青函隧道", "英法海底隧道", "秦岭终南山隧道"], answer: 0, explanation: "瑞士圣哥达基线隧道全长57.09公里，是世界上最长的铁路隧道（也是最长的陆地隧道）。圣哥达基线隧道穿越阿尔卑斯山，2016年贯通，2021年全面运营。新关角隧道32.645公里是中国最长的铁路隧道。" },
  { q: "世界上最长的公路隧道是？", options: ["挪威洛达尔隧道", "秦岭终南山隧道", "瑞士圣哥达公路隧道", "法国-意大利勃朗峰隧道"], answer: 0, explanation: "挪威洛达尔公路隧道全长24.51公里，是世界上最长的公路隧道。洛达尔隧道于2000年通车，穿越挪威西部山区。秦岭终南山公路隧道全长18.02公里，是中国最长的公路隧道。" },
  { q: "世界上最长的跨海大桥是？", options: ["港珠澳大桥", "杭州湾跨海大桥", "青岛海湾大桥", "金门大桥"], answer: 0, explanation: "港珠澳大桥全长55公里（含主体工程和接线），是世界上最长的跨海大桥系统。港珠澳大桥连接香港、珠海和澳门，2018年10月通车。大桥包括桥梁、海底隧道和人工岛，是'超级工程'的代表。" },
  { q: "世界上最高的建筑是？", options: ["哈利法塔", "上海中心大厦", "麦加皇家钟塔", "深圳平安金融中心"], answer: 0, explanation: "哈利法塔（原名迪拜塔）位于阿联酋迪拜，高828米，是世界上最高的建筑。哈利法塔2010年建成，有163层。上海中心大厦高632米，是中国最高建筑，世界第二高。哈利法塔是阿联酋标志性建筑。" },
  { q: "中国最高的建筑是？", options: ["上海中心大厦", "深圳平安金融中心", "广州塔", "天津117大厦"], answer: 0, explanation: "上海中心大厦高632米，是中国最高的建筑，也是世界第二高建筑（仅次于迪拜哈利法塔828米）。上海中心大厦位于上海陆家嘴，2015年建成，有128层。深圳平安金融中心高599米，是中国第二高建筑。" },
  { q: "世界上最大的经济体是？", options: ["美国", "中国", "日本", "德国"], answer: 0, explanation: "美国是世界上最大的经济体，GDP约25万亿美元。中国是世界第二大经济体，GDP约18万亿美元。日本第三，德国第四。美国和中国是仅有的两个GDP超过10万亿美元的国家。按购买力平价（PPP）计，中国超过美国。" },
  { q: "世界上面积超过900万平方千米的国家有几个？", options: ["4个", "3个", "2个", "5个"], answer: 0, explanation: "世界上面积超过900万平方千米的国家有4个：俄罗斯（1709万）、加拿大（998万）、中国（960万）、美国（937万）。这四个国家也被称为'领土大国'。巴西面积851万平方千米紧随其后居第五。" },
  { q: "赤道穿过的大洲不包括？", options: ["欧洲", "非洲", "亚洲", "南美洲"], answer: 0, explanation: "赤道不穿过欧洲。赤道穿过非洲（中部）、亚洲（印度尼西亚）、南美洲（亚马逊河流域）和大洋洲（部分印尼岛屿）。非洲是被赤道穿过最长的大洲。欧洲完全位于北半球，赤道不经过欧洲。" },
  { q: "北回归线穿过的大洲不包括？", options: ["欧洲", "非洲", "亚洲", "北美洲"], answer: 0, explanation: "北回归线（23.5°N）不穿过欧洲。北回归线穿过非洲（撒哈拉沙漠）、亚洲（阿拉伯半岛、印度北部、中国南部）、北美洲（墨西哥）。北回归线附近多为热带沙漠气候，世界主要沙漠分布在此区域。" },
  { q: "南极洲位于哪个纬度范围内？", options: ["南极圈以内", "赤道附近", "北回归线附近", "北极圈以内"], answer: 0, explanation: "南极洲位于南极圈（66.5°S）以内，是地球上最南端的大洲。南极洲面积约1400万平方千米，98%的土地被冰雪覆盖。南极洲是世界上最冷、最干燥、风最大的大洲，也是世界上唯一没有永久居民的大洲。" },
  { q: "北极地区主要包括哪个海洋？", options: ["北冰洋", "大西洋", "太平洋", "南极海"], answer: 0, explanation: "北极地区主要包括北冰洋及其周边陆地。北冰洋面积约1475万平方千米，是四大洋中最小的。北极点位于北冰洋上。北极地区有北极熊、海象等特有动物。与南极洲不同，北极地区没有永久陆地。" },
  { q: "世界上唯一没有永久居民的大洲是？", options: ["南极洲", "大洋洲", "北极", "格陵兰"], answer: 0, explanation: "南极洲是世界上唯一没有永久居民的大洲。南极洲有科学考察站的科研人员（季节性），但没有常住人口。《南极条约》（1959年）规定南极洲仅用于和平目的，禁止军事活动和矿产资源开发。" },
  { q: "《南极条约》签署于哪一年？", options: ["1959年", "1961年", "1955年", "1965年"], answer: 0, explanation: "《南极条约》于1959年12月1日在华盛顿签署，1961年6月23日生效。《南极条约》规定南极洲仅用于和平目的，禁止军事活动、核试验和废物处理，保障科学考察自由。中国1983年加入《南极条约》，1985年建长城站。" },
  { q: "中国在南极的第一个科学考察站是？", options: ["长城站", "中山站", "昆仑站", "泰山站"], answer: 0, explanation: "中国在南极的第一个科学考察站是长城站，1985年2月建于南极乔治王岛。中山站（1989年）、昆仑站（2009年）、泰山站（2014年）随后建成。中国第五个南极考察站秦岭站于2024年2月建成。" },
  { q: "中国在北极的第一个科学考察站是？", options: ["黄河站", "长城站", "中山站", "昆仑站"], answer: 0, explanation: "中国在北极的第一个科学考察站是黄河站，2004年建于挪威斯瓦尔巴群岛的新奥尔松。黄河站是中国首个北极考察站。中国后续在冰岛建成中-冰北极科学考察站（2018年）。中国是'近北极国家'。" },
  { q: "《巴黎协定》签署于哪一年？", options: ["2015年", "2013年", "2016年", "2014年"], answer: 0, explanation: "《巴黎协定》于2015年12月12日在巴黎气候变化大会上通过，2016年11月4日生效。《巴黎协定》旨在将全球升温控制在2°C以内（努力争取1.5°C）。中国于2016年4月签署《巴黎协定》。" },
  { q: "《京都议定书》签署于哪一年？", options: ["1997年", "1995年", "2000年", "2005年"], answer: 0, explanation: "《京都议定书》于1997年12月在日本京都签署，2005年2月正式生效。《京都议定书》是第一个约束发达国家温室气体排放的国际法律文件。《京都议定书》第一承诺期2008-2012年，第二承诺期2013-2020年。" },
  { q: "《联合国气候变化框架公约》签署于哪一年？", options: ["1992年", "1990年", "1995年", "1997年"], answer: 0, explanation: "《联合国气候变化框架公约》（UNFCCC）于1992年5月9日在纽约通过，1994年3月21日生效。公约缔约方会议（COP）每年举行，COP21（2015年巴黎）通过《巴黎协定》，COP15（2021年昆明/2022年蒙特利尔）通过'昆蒙框架'。" },
  { q: "联合国可持续发展目标（SDGs）共有多少个？", options: ["17个", "8个", "15个", "20个"], answer: 0, explanation: "联合国可持续发展目标（SDGs）共有17个，2015年9月在联合国发展峰会上通过，目标是2030年实现。17个SDG包括消除贫困、消除饥饿、健康、教育、性别平等、清洁饮水、清洁能源、气候行动等。" },
  { q: "世界三大宗教是？", options: ["基督教、伊斯兰教、佛教", "基督教、犹太教、伊斯兰教", "佛教、印度教、伊斯兰教", "基督教、伊斯兰教、印度教"], answer: 0, explanation: "世界三大宗教是基督教、伊斯兰教和佛教。基督教是世界上信徒最多的宗教（约24亿），伊斯兰教第二（约19亿），佛教第三（约5亿）。印度教信徒约12亿但主要分布在印度。犹太教是三大一神教的源头。" },
  { q: "世界上信徒最多的宗教是？", options: ["基督教", "伊斯兰教", "佛教", "印度教"], answer: 0, explanation: "基督教是世界上信徒最多的宗教，约有24亿信徒，占全球人口的31%。基督教主要分布在欧洲、美洲和大洋洲。伊斯兰教约有19亿信徒，是第二大宗教，主要分布在中东、北非和南亚。印度教约有12亿信徒。" },
  { q: "联合国总部位于哪个城市？", options: ["纽约", "日内瓦", "布鲁塞尔", "维也纳"], answer: 0, explanation: "联合国总部位于美国纽约。联合国成立于1945年10月24日（联合国日），有193个成员国。联合国总部大楼位于纽约曼哈顿。联合国在日内瓦、维也纳和内罗毕设有办事处。国际法院位于荷兰海牙。" },
  { q: "国际法院位于哪个城市？", options: ["海牙", "纽约", "日内瓦", "布鲁塞尔"], answer: 0, explanation: "国际法院（ICJ）位于荷兰海牙。国际法院是联合国的主要司法机关，1945年成立，负责审理国家间争端。国际法院不同于国际刑事法院（ICC，也位于海牙）。中国是国际法院成员国，曾有中国法官担任国际法院法官。" },
  { q: "世界贸易组织（WTO）总部位于哪个城市？", options: ["日内瓦", "纽约", "布鲁塞尔", "巴黎"], answer: 0, explanation: "世界贸易组织（WTO）总部位于瑞士日内瓦。WTO成立于1995年（前身为GATT），有160多个成员国。WTO是处理国际贸易规则的国际组织。中国于2001年12月11日加入WTO。" },
  { q: "国际货币基金组织（IMF）总部位于哪个城市？", options: ["华盛顿", "纽约", "日内瓦", "布鲁塞尔"], answer: 0, explanation: "国际货币基金组织（IMF）总部位于美国华盛顿。IMF成立于1944年（布雷顿森林会议），有190个成员国。IMF旨在促进国际货币合作和金融稳定。IMF与世界银行同在华盛顿。中国是IMF创始成员国，在IMF份额排第三。" },
  { q: "世界银行总部位于哪个城市？", options: ["华盛顿", "纽约", "日内瓦", "伦敦"], answer: 0, explanation: "世界银行（World Bank）总部位于美国华盛顿。世界银行成立于1944年（布雷顿森林会议），有189个成员国。世界银行旨在为发展中国家提供贷款和技术援助。世界银行与IMF同在华盛顿。中国是世界银行创始成员国之一。" },
  { q: "亚洲基础设施投资银行（AIIB）总部位于哪个城市？", options: ["北京", "上海", "香港", "新加坡"], answer: 0, explanation: "亚洲基础设施投资银行（AIIB）总部位于中国北京。AIIB成立于2015年，2016年1月正式运营，有100多个成员国。AIIB旨在为亚洲基础设施建设提供融资支持。AIIB是中国发起设立的国际多边开发银行，首任行长为金立群。" },
  { q: "上海合作组织（SCO）秘书处位于哪个城市？", options: ["北京", "上海", "莫斯科", "塔什干"], answer: 0, explanation: "上海合作组织（SCO）秘书处位于中国北京。SCO成立于2001年（前身'上海五国'机制），有中国、俄罗斯、哈萨克斯坦、吉尔吉斯斯坦、塔吉克斯坦、乌兹别克斯坦、印度、巴基斯坦和伊朗等成员国。SCO地区反恐怖机构执委会在塔什干。" },
  { q: "金砖国家（BRICS）最初包括哪些国家？", options: ["巴西、俄罗斯、印度、中国、南非", "巴西、俄罗斯、印度、中国", "巴西、俄罗斯、印度、中国、南非、阿根廷", "巴西、俄罗斯、印度、中国、南非、韩国"], answer: 0, explanation: "金砖国家（BRICS）最初包括巴西、俄罗斯、印度、中国和南非五国。2024年金砖扩员，新增埃及、埃塞俄比亚、伊朗、阿联酋等国。金砖国家合作机制是新兴市场国家和发展中国家的重要合作平台，人口和经济总量占全球重要比重。" },
  { q: "二十国集团（G20）包括多少个国家和组织？", options: ["19个国家+欧盟+非盟", "20个国家", "18个国家", "21个国家"], answer: 0, explanation: "二十国集团（G20）包括19个国家（阿根廷、澳大利亚、巴西、加拿大、中国、法国、德国、印度、印度尼西亚、意大利、日本、韩国、墨西哥、俄罗斯、沙特阿拉伯、南非、土耳其、英国、美国）+欧盟+非洲联盟（2023年加入）。G20峰会每年举行。" },
  { q: "联合国教科文组织总部位于？", options: ["巴黎", "日内瓦", "纽约", "罗马"], answer: 0, explanation: "联合国教科文组织（UNESCO）总部位于法国巴黎。UNESCO成立于1945年，是联合国专门机构之一，旨在通过教育、科学、文化促进国际合作。UNESCO管理世界遗产名录、人与生物圈保护区等项目。中国是UNESCO创始成员国之一。" },
  { q: "联合国教科文组织世界遗产名录截至2025年共有约多少处？", options: ["约1200处", "约1000处", "约1500处", "约800处"], answer: 0, explanation: "截至2025年，联合国教科文组织世界遗产名录共有约1200处（约950处文化遗产、约200处自然遗产和约50处双重遗产）。中国有59处世界遗产，位居世界第二（仅次于意大利）。1972年联合国教科文组织通过《世界遗产公约》。" },
  { q: "世界上世界遗产数量最多的国家是？", options: ["意大利", "中国", "西班牙", "法国"], answer: 0, explanation: "意大利是世界上世界遗产数量最多的国家，约60处。中国59处居第二。西班牙约50处居第三。意大利和中国是世界遗产数量最多的两个国家。意大利有罗马历史中心、威尼斯、佛罗伦萨等著名世界遗产。" },
  { q: "世界上海拔最高的首都是？", options: ["拉巴斯（玻利维亚）", "拉萨（中国）", "基多（厄瓜多尔）", "亚的斯亚贝巴（埃塞俄比亚）"], answer: 0, explanation: "玻利维亚的行政首都拉巴斯是世界海拔最高的首都，海拔约3640米。厄瓜多尔首都基多海拔约2850米，居第二。玻利维亚法定首都是苏克雷（司法首都），但政府机关在拉巴斯。拉萨海拔约3650米，是中国海拔最高的省会城市。" },
  { q: "世界上最北的首都是？", options: ["雷克雅未克（冰岛）", "赫尔辛基（芬兰）", "奥斯陆（挪威）", "斯德哥尔摩（瑞典）"], answer: 0, explanation: "冰岛首都雷克雅未克（约64°N）是世界上独立国家中最北的首都。雷克雅未克位于冰岛西南部。赫尔辛基（约60°N）和奥斯陆（约59.9°N）也很靠北。如果包括自治领，格陵兰首府努克（约64°N）也很靠北。" },
  { q: "世界上最南的首都是？", options: ["惠灵顿（新西兰）", "堪培拉（澳大利亚）", "布宜诺斯艾利斯（阿根廷）", "圣地亚哥（智利）"], answer: 0, explanation: "新西兰首都惠灵顿（约41°S）是世界上独立国家中最南的首都。惠灵顿位于新西兰北岛南端。堪培拉约35°S，布宜诺斯艾利斯约34°S。惠灵顿地处库克海峡，风大，被称为'风城'。" },
  { q: "赤道穿过的非洲国家最多，赤道穿过的非洲国家有几个？", options: ["6个", "4个", "5个", "7个"], answer: 0, explanation: "赤道穿过非洲6个国家：圣多美和普林西比、加蓬、刚果共和国、刚果民主共和国、乌干达、肯尼亚（以及索马里边境附近）。非洲是赤道穿过最长大洲。赤道附近非洲国家气候多为热带雨林或热带草原气候。" },
  { q: "赤道穿过的亚洲国家是？", options: ["印度尼西亚", "马来西亚", "印度", "菲律宾"], answer: 0, explanation: "赤道穿过亚洲的印度尼西亚（加里曼丹岛、苏门答腊岛等）。赤道也经过马尔代夫等岛国。马来西亚不在赤道上（约1-7°N）。印度尼西亚是亚洲唯一被赤道穿过的主要国家。赤道附近印度尼西亚为热带雨林气候。" },
  { q: "南极洲是世界上唯一没有哪个的大洲？", options: ["永久居民", "动物", "植物", "冰雪"], answer: 0, explanation: "南极洲是世界上唯一没有永久居民的大洲。南极洲有科学考察站的科研人员（季节性），但没有常住人口。《南极条约》（1959年）规定南极洲仅用于和平目的。南极洲有企鹅、海豹等动物，有苔藓等植物，有冰雪覆盖。" },
  { q: "世界上最大的经济体美国的首都华盛顿位于哪个特区？", options: ["哥伦比亚特区", "纽约特区", "马里兰州", "弗吉尼亚州"], answer: 0, explanation: "美国首都华盛顿全称华盛顿哥伦比亚特区（Washington D.C.），位于马里兰州和弗吉尼亚州之间的哥伦比亚特区。华盛顿特区是美国联邦直辖区，不属于任何州。华盛顿有白宫、国会大厦、林肯纪念堂等标志性建筑。" },

  // ========== 环境问题（301-400） ==========
  { q: "全球变暖的主要原因是？", options: ["温室气体排放增加", "太阳辐射增强", "地球自转减慢", "火山喷发"], answer: 0, explanation: "全球变暖的主要原因是人类活动排放的温室气体（CO2、CH4等）大幅增加，增强了大气的温室效应。温室气体主要来自化石燃料燃烧、工业生产和森林砍伐。IPCC报告确认人类活动是全球变暖的主因。" },
  { q: "温室气体中浓度增加最快的是？", options: ["二氧化碳", "甲烷", "氧化亚氮", "氟利昂"], answer: 0, explanation: "二氧化碳（CO2）是浓度增加最快的温室气体，也是对全球变暖贡献最大的温室气体。CO2浓度从工业革命前约280ppm增加到2024年约425ppm。CO2主要来自化石燃料燃烧（煤、石油、天然气）。CO2占温室效应约60%。" },
  { q: "温室气体中增温效应最强的是？", options: ["氟利昂（CFCs）", "二氧化碳", "甲烷", "水蒸气"], answer: 0, explanation: "氟利昂（CFCs）的增温效应是二氧化碳的数千倍，是增温效应最强的温室气体。但CFCs浓度远低于CO2。CFCs同时破坏臭氧层。《蒙特利尔议定书》（1987年）已限制CFCs的生产和使用，但替代品HFCs也有温室效应。" },
  { q: "《巴黎协定》的目标是将全球升温控制在多少度以内？", options: ["2°C以内（争取1.5°C）", "1°C以内", "3°C以内", "4°C以内"], answer: 0, explanation: "《巴黎协定》的目标是将全球平均升温控制在工业化前2°C以内，并努力争取控制在1.5°C以内。科学研究表明1.5°C是避免最严重气候变化影响的关键阈值。2018年IPCC报告强调了1.5°C目标的重要性。" },
  { q: "全球变暖导致的后果不包括？", options: ["海平面下降", "冰川退缩", "极端天气增多", "海平面上升"], answer: 0, explanation: "全球变暖导致海平面上升而非下降。全球变暖导致冰川和极地冰盖融化、海水热膨胀，使海平面上升。全球变暖还导致极端天气增多（热浪、暴雨、干旱等）、生态系统破坏和生物多样性减少。" },
  { q: "臭氧层破坏的主要原因是？", options: ["氟利昂排放", "二氧化碳排放", "甲烷排放", "二氧化硫排放"], answer: 0, explanation: "臭氧层破坏的主要原因是氟利昂（CFCs）等含氯氟烃化合物的排放。CFCs在平流层中分解释放氯原子，氯原子催化破坏臭氧分子。1987年《蒙特利尔议定书》限制CFCs生产使用，臭氧层正在缓慢恢复。" },
  { q: "臭氧层破坏对人类的主要危害是？", options: ["紫外线增多导致皮肤癌", "气温升高", "降雨减少", "海平面上升"], answer: 0, explanation: "臭氧层破坏导致到达地表的紫外线增多，增加皮肤癌、白内障等疾病发病率，也会影响农作物和海洋生态系统。1987年《蒙特利尔议定书》限制CFCs排放后，南极臭氧空洞正在缓慢缩小，预计本世纪中叶恢复。" },
  { q: "南极臭氧空洞发现于哪一年？", options: ["1985年", "1980年", "1990年", "1975年"], answer: 0, explanation: "1985年英国科学家在南极上空发现臭氧层大幅减少的现象，被称为'臭氧空洞'。臭氧空洞每年南半球春季（9-11月）最为严重。《蒙特利尔议定书》（1987年）限制CFCs排放后，臭氧空洞正在缓慢缩小，预计本世纪中叶恢复。" },
  { q: "《蒙特利尔议定书》签署于哪一年？", options: ["1987年", "1985年", "1990年", "1992年"], answer: 0, explanation: "《蒙特利尔议定书》（全称《关于消耗臭氧层物质的蒙特利尔议定书》）于1987年9月16日在蒙特利尔签署，1989年1月1日生效。议定书限制CFCs等消耗臭氧层物质的生产和使用。议定书被公认是最成功的国际环境协议之一，臭氧层正在恢复。" },
  { q: "酸雨的主要成因是？", options: ["二氧化硫和氮氧化物排放", "二氧化碳排放", "甲烷排放", "氟利昂排放"], answer: 0, explanation: "酸雨的主要成因是二氧化硫（SO2）和氮氧化物（NOx）的排放。SO2和NOx主要来自燃煤和汽车尾气，在大气中与水蒸气反应形成硫酸和硝酸，随降水落到地面形成酸雨。酸雨危害植物、土壤、水体和建筑物。" },
  { q: "酸雨的pH值标准是？", options: ["小于5.6", "小于7", "小于4", "小于6"], answer: 0, explanation: "正常雨水因溶解CO2呈弱酸性（pH约5.6）。pH值低于5.6的降水称为酸雨。酸雨的酸性主要来自SO2和NOx形成的硫酸和硝酸。中国南方是酸雨较严重的地区，主要因燃煤排放SO2。近年来因脱硫措施酸雨有所改善。" },
  { q: "中国酸雨最严重的地区是？", options: ["南方地区", "北方地区", "西北地区", "青藏高原"], answer: 0, explanation: "中国南方地区酸雨较严重，因南方燃煤含硫量高且土壤偏酸性，对酸雨缓冲能力弱。四川盆地、贵州、湖南、江西等地是酸雨严重区。近年来因脱硫措施和清洁能源替代，酸雨有所改善。北方土壤偏碱性，对酸雨缓冲能力强。" },
  { q: "生物多样性减少的主要原因是？", options: ["栖息地破坏", "全球变暖", "自然灾害", "太阳活动"], answer: 0, explanation: "生物多样性减少的主要原因是栖息地破坏（森林砍伐、湿地填埋、草原开垦等），其次是过度开发、环境污染、外来物种入侵和气候变化。人类活动是生物多样性减少的根本原因。全球约100万种动植物面临灭绝威胁。" },
  { q: "《生物多样性公约》签署于哪一年？", options: ["1992年", "1990年", "1995年", "1997年"], answer: 0, explanation: "《生物多样性公约》（CBD）于1992年6月5日在里约热内卢联合国环境与发展大会上签署，1993年12月29日生效。公约旨在保护生物多样性、可持续利用其组成部分和公平合理分享由利用遗传资源而产生的惠益。中国是最早缔约国之一。" },
  { q: "中国承办《生物多样性公约》COP15大会的城市是？", options: ["昆明", "北京", "上海", "成都"], answer: 0, explanation: "《生物多样性公约》第十五次缔约方大会（COP15）在中国云南省昆明市召开。2021年10月第一阶段会议在昆明举行，2022年12月第二阶段会议在加拿大蒙特利尔举行（中国主席国，东道国为昆明）。大会通过了'昆蒙框架'。" },
  { q: "'昆明-蒙特利尔全球生物多样性框架'设定的目标是到2030年保护至少多少的陆地和海洋？", options: ["30%", "20%", "40%", "50%"], answer: 0, explanation: "'昆明-蒙特利尔全球生物多样性框架'设定了到2030年保护至少30%的陆地和海洋的目标（'3030目标'）。框架还包括恢复30%的退化生态系统、减少农药使用等23项目标。该框架被称为全球生物多样性保护的里程碑。" },
  { q: "土地荒漠化的主要原因是？", options: ["过度放牧和开垦", "全球变暖", "自然灾害", "太阳活动"], answer: 0, explanation: "土地荒漠化的主要原因是过度放牧、过度开垦、水资源不合理利用和森林砍伐等人类活动。气候变化加剧了荒漠化进程。荒漠化影响全球约40%的陆地面积和20多亿人口。中国是受荒漠化影响最严重的国家之一。" },
  { q: "《联合国防治荒漠化公约》签署于哪一年？", options: ["1994年", "1992年", "1996年", "1990年"], answer: 0, explanation: "《联合国防治荒漠化公约》（UNCCD）于1994年6月17日在巴黎签署，1996年12月26日生效。公约旨在通过国际合作防治荒漠化和干旱。6月17日被定为'世界防治荒漠化和干旱日'。中国是受荒漠化影响最严重的国家之一，也是公约积极履约国。" },
  { q: "中国荒漠化土地面积约为？", options: ["约257万平方千米", "约100万平方千米", "约150万平方千米", "约200万平方千米"], answer: 0, explanation: "中国荒漠化土地面积约257万平方千米，占国土面积的26.8%。荒漠化主要分布在西北、华北和东北西部地区。通过三北防护林等工程，中国荒漠化面积近年来持续减少，实现了从'沙进人退'到'绿进沙退'的转变。" },
  { q: "中国'三北防护林'工程的目的是？", options: ["防风固沙、保持水土", "发展林业经济", "美化环境", "提供木材"], answer: 0, explanation: "三北防护林工程的主要目的是防风固沙、保持水土、改善生态环境。工程覆盖东北、华北、西北13个省区，1978年启动，预计2050年完工。三北防护林被称为'绿色长城'，是世界上最大的生态工程，有效遏制了荒漠化扩展。" },
  { q: "中国'退耕还林还草'工程的目的是？", options: ["减少水土流失，改善生态", "增加耕地面积", "发展牧业", "提供木材"], answer: 0, explanation: "退耕还林还草工程的目的是将坡耕地退耕还林还草，减少水土流失，改善生态环境，同时促进农民增收。1999年试点，2002年全面启动。退耕还林还草是中国最大的生态补偿工程，累计退耕还林还草数亿亩，显著改善了生态。" },
  { q: "可持续发展理念的核心是？", options: ["既满足当代人需要又不损害后代人满足需要的能力", "经济增长优先", "环境保护优先", "社会发展优先"], answer: 0, explanation: "可持续发展理念的核心是'既满足当代人的需要，又不对后代人满足其需要的能力构成危害'。1987年世界环境与发展委员会《我们共同的未来》报告首次提出。可持续发展强调经济、社会、环境三大支柱协调统一。" },
  { q: "可持续发展理念首次提出于哪一年？", options: ["1987年", "1980年", "1992年", "1990年"], answer: 0, explanation: "可持续发展理念由1987年世界环境与发展委员会（布伦特兰委员会）报告《我们共同的未来》首次正式提出。1992年里约联合国环境与发展大会将可持续发展确立为全球战略。可持续发展成为国际社会普遍认同的发展理念。" },
  { q: "联合国环境与发展大会（里约地球峰会）召开于哪一年？", options: ["1992年", "1990年", "1995年", "1987年"], answer: 0, explanation: "1992年6月在巴西里约热内卢召开联合国环境与发展大会（'里约地球峰会'）。大会通过了《里约宣言》和《21世纪议程》，签署了《生物多样性公约》和《气候变化框架公约》。这是首次将可持续发展确立为全球战略的大会。" },
  { q: "《21世纪议程》通过于哪一年？", options: ["1992年", "1990年", "1995年", "2000年"], answer: 0, explanation: "《21世纪议程》于1992年里约联合国环境与发展大会上通过。《21世纪议程》是可持续发展的全球行动计划，涵盖社会、经济和环境等领域。1992年大会还通过了《里约宣言》，签署了《生物多样性公约》和《气候变化框架公约》。" },
  { q: "中国'碳达峰'目标年份是？", options: ["2030年", "2025年", "2035年", "2050年"], answer: 0, explanation: "中国承诺在2030年前实现碳排放达峰（碳达峰）。2020年9月习近平在联合国大会上宣布中国力争2030年前实现碳达峰、2060年前实现碳中和。这被称为'3060'双碳目标，是中国应对气候变化的庄严承诺。" },
  { q: "中国'碳中和'目标年份是？", options: ["2060年", "2050年", "2030年", "2080年"], answer: 0, explanation: "中国承诺在2060年前实现碳中和。2020年9月习近平在联合国大会上宣布中国力争2030年前实现碳达峰、2060年前实现碳中和。这被称为'3060'双碳目标。碳中和意味着净碳排放为零，需要通过减排和碳汇/碳捕集实现。" },
  { q: "中国'3060'双碳目标提出于哪一年？", options: ["2020年", "2018年", "2019年", "2021年"], answer: 0, explanation: "2020年9月22日，习近平在第七十五届联合国大会一般性辩论上宣布中国'3060'双碳目标：力争2030年前实现碳达峰、2060年前实现碳中和。这是中国应对气候变化的庄严承诺，也是中国绿色低碳发展的战略目标。" },
  { q: "中国'全国碳市场'上线交易的时间是？", options: ["2021年7月", "2019年", "2020年", "2022年"], answer: 0, explanation: "2021年7月16日，全国碳排放权交易市场（全国碳市场）上线交易正式启动。全国碳市场是全球覆盖温室气体排放量最大的碳市场。首批纳入发电行业，后续将逐步扩大到其他行业。全国碳市场是中国实现双碳目标的重要市场机制。" },
  { q: "中国'全国生态日'是每年的？", options: ["8月15日", "6月5日", "3月12日", "4月22日"], answer: 0, explanation: "2023年6月28日，全国人大常委会决定将8月15日设立为'全国生态日'。8月15日是2005年习近平提出'绿水青山就是金山银山'理念的日子。全国生态日的设立旨在增强全民生态环保意识，是中国生态文明建设的重要举措。" },
  { q: "中国'绿水青山就是金山银山'理念提出于哪一年？", options: ["2005年", "2003年", "2010年", "2012年"], answer: 0, explanation: "2005年8月15日，习近平在浙江湖州安吉余村考察时首次提出'绿水青山就是金山银山'的理念。2017年该理念写入党的十九大报告和新党章。'两山论'是中国生态文明建设的核心理念之一，强调生态保护和经济发展的统一。" },
  { q: "中国'生态文明建设'纳入'五位一体'总体布局的时间是？", options: ["2012年", "2010年", "2015年", "2018年"], answer: 0, explanation: "2012年党的十八大将生态文明建设纳入'五位一体'总体布局（经济、政治、文化、社会、生态文明建设），标志着生态文明建设提升到国家战略高度。2018年'生态文明'写入宪法。生态文明是中国式现代化的重要特征。" },
  { q: "中国'美丽中国'建设目标实现的时间节点是？", options: ["2035年基本实现，2050年全面建成", "2030年基本实现", "2040年基本实现", "2025年基本实现"], answer: 0, explanation: "中国'美丽中国'建设目标是：到2035年基本实现美丽中国目标，到2050年全面建成美丽中国。2023年全国生态环境保护大会提出全面推进美丽中国建设。美丽中国是生态文明建设的目标，也是中国式现代化的重要内容。" },
  { q: "中国'生态环境部'组建于哪一年？", options: ["2018年", "2016年", "2017年", "2019年"], answer: 0, explanation: "2018年3月，国务院机构改革组建生态环境部，整合了原环境保护部等职责。生态环境部统一行使生态和城乡各类污染排放监管和行政执法职责。生态环境部的组建标志着中国生态环境管理体制进入新阶段。" },
  { q: "中国'自然资源部'组建于哪一年？", options: ["2018年", "2016年", "2017年", "2019年"], answer: 0, explanation: "2018年3月，国务院机构改革组建自然资源部，整合了原国土资源部、国家林业局、国家海洋局、国家测绘地理信息局等职责。自然资源部统一行使全民所有自然资源资产所有者职责，统一行使所有国土空间用途管制职责。" },
  { q: "中国'三北防护林'工程启动于哪一年？", options: ["1978年", "1980年", "1985年", "1990年"], answer: 0, explanation: "三北防护林工程于1978年启动，计划到2050年完工，历时73年。工程分八期进行，目前已进入第六期（2021-2030年）。三北防护林工程覆盖东北、华北、西北13个省区，是世界上最最大的生态工程，被称为'绿色长城'。" },
  { q: "中国'退耕还林还草'工程启动于哪一年？", options: ["1999年", "1995年", "2000年", "2002年"], answer: 0, explanation: "退耕还林还草工程于1999年开始试点，2002年全面启动。该工程将坡耕地退耕还林还草，减少水土流失，改善生态环境。退耕还林还草是中国最大的生态补偿工程，累计退耕还林还草数亿亩。" },
  { q: "中国'天然林保护'工程启动于哪一年？", options: ["1998年", "1995年", "2000年", "2002年"], answer: 0, explanation: "天然林保护工程于1998年启动（试点），2000年全面实施。该工程全面停止天然林商业性采伐，保护天然林资源。2016年起全面停止天然林商业性采伐。天然林保护工程覆盖全国，是中国最重要的生态工程之一。" },
  { q: "中国'河长制'全面推行的时间是？", options: ["2018年", "2016年", "2017年", "2019年"], answer: 0, explanation: "2018年1月，中共中央办公厅、国务院办公厅印发《关于全面推行河长制的意见》，标志着河长制在全国全面推行。河长制由各级党政负责人担任河长，负责河湖管理和保护，是中国水治理体制的重要创新。" },
  { q: "中国'林长制'全面推行的时间是？", options: ["2021年", "2019年", "2020年", "2022年"], answer: 0, explanation: "2021年1月，中共中央办公厅、国务院办公厅印发《关于全面推行林长制的意见》，标志着林长制在全国全面推行。林长制由各级党政负责人担任林长，负责森林草原资源保护发展，是生态文明制度的重要创新。" },
  { q: "中国'国家公园'体制的试点开始于哪一年？", options: ["2015年", "2013年", "2016年", "2018年"], answer: 0, explanation: "2015年开始国家公园体制试点，先后在青海、吉林、黑龙江、四川、陕西、甘肃、福建、江西、海南、浙江等省份设立10个国家公园体制试点区。2021年正式设立首批5个国家公园，标志着试点结束。" },
  { q: "中国首批国家公园的数量是？", options: ["5个", "3个", "4个", "6个"], answer: 0, explanation: "2021年9月，中国正式设立首批5个国家公园：三江源国家公园、大熊猫国家公园、东北虎豹国家公园、海南热带雨林国家公园、武夷山国家公园。这5个国家公园代表了中国最重要的自然生态系统和珍稀物种栖息地。" },
  { q: "中国首批国家公园中面积最大的是？", options: ["三江源国家公园", "大熊猫国家公园", "东北虎豹国家公园", "海南热带雨林国家公园"], answer: 0, explanation: "三江源国家公园是中国首批国家公园中面积最大的，面积19.07万平方千米，位于青海省南部。三江源是长江、黄河、澜沧江的源头地区，被称为'中华水塔'，生态地位极为重要。" },
  { q: "中国'生态保护红线'面积占国土面积的比例约为？", options: ["25%以上", "15%", "30%", "20%"], answer: 0, explanation: "中国生态保护红线面积约占国土面积的25%以上，涵盖生态功能极重要、生态极脆弱的关键区域。生态保护红线包括水源涵养、生物多样性维护、水土保持等生态功能重要区，是中国生态安全的底线和生命线。" },
  { q: "中国'长江保护法'实施于哪一年？", options: ["2021年", "2019年", "2020年", "2022年"], answer: 0, explanation: "2021年3月1日，《中华人民共和国长江保护法》正式实施。这是中国首部流域性法律，旨在保护长江流域生态环境。长江保护法实施'共抓大保护、不搞大开发'，推动长江经济带绿色发展。" },
  { q: "中国'黄河保护法'实施于哪一年？", options: ["2023年", "2021年", "2022年", "2024年"], answer: 0, explanation: "2023年4月1日，《中华人民共和国黄河保护法》正式实施。黄河保护法是中国第二部流域性法律，旨在保护黄河流域生态环境。黄河保护法的实施标志着中国流域生态保护法律体系的进一步完善。" },
  { q: "中国'黑土地保护法'实施于哪一年？", options: ["2022年", "2020年", "2021年", "2023年"], answer: 0, explanation: "2022年8月1日，《中华人民共和国黑土地保护法》正式实施。这是中国首次对黑土地保护立法，旨在保护东北黑土地这一珍贵的土壤资源。东北黑土地是中国重要的粮食生产基地，被誉为'耕地中的大熊猫'。" },
  { q: "中国'湿地保护法'实施于哪一年？", options: ["2022年", "2020年", "2021年", "2023年"], answer: 0, explanation: "2022年6月1日，《中华人民共和国湿地保护法》正式实施。这是中国首部湿地保护专门法律，旨在保护湿地生态系统。中国湿地面积约3.53亿亩，湿地保护法将湿地保护纳入法治轨道，是生态文明制度建设的重要里程碑。" },
  { q: "中国耕地保护红线是多少亿亩？", options: ["18亿亩", "19亿亩", "20亿亩", "17亿亩"], answer: 0, explanation: "中国耕地保护红线为18亿亩。2006年'十一五'规划纲要首次提出18亿亩耕地红线。这是保障国家粮食安全的底线，任何单位和个人不得擅自占用基本农田。中国实行最严格的耕地保护制度。" },
  { q: "中国'第三次全国国土调查'显示全国耕地面积为？", options: ["19.18亿亩", "20.18亿亩", "18.18亿亩", "21.18亿亩"], answer: 0, explanation: "第三次全国国土调查显示，全国耕地面积为19.18亿亩。这一数据比第二次全国土地调查（2009年）减少了1.13亿亩。耕地保护红线为18亿亩，中国实行最严格的耕地保护制度和节约用地制度。" },
  { q: "中国'三区三线'中的'三线'是指？", options: ["城镇开发边界、永久基本农田、生态保护红线", "海岸线、国境线、铁路线", "经线、纬线、本初子午线", "公路、铁路、航空线"], answer: 0, explanation: "'三区三线'中的'三线'指城镇开发边界、永久基本农田和生态保护红线。'三区'指城镇空间、农业空间和生态空间。'三区三线'是国土空间规划的核心内容，旨在优化国土空间开发保护格局。" },
  { q: "中国'山水林田湖草沙冰'一体化保护和系统治理理念体现了什么？", options: ["生态系统整体性", "各部门分别治理", "只保护森林", "只保护草原"], answer: 0, explanation: "'山水林田湖草沙冰'一体化保护和系统治理理念体现了生态系统的整体性。各类自然要素相互依存、紧密联系，必须整体保护、系统修复、综合治理。这一理念是习近平生态文明思想的重要内容，强调用系统工程思路治理生态问题。" },
  { q: "中国'青藏高原生态保护法'实施于哪一年？", options: ["2023年", "2021年", "2022年", "2024年"], answer: 0, explanation: "2023年9月1日，《中华人民共和国青藏高原生态保护法》正式实施。该法是国家针对特定区域生态保护的重要立法，旨在保护青藏高原生态系统，维护生态安全。青藏高原是'亚洲水塔'，生态地位极为重要。" },
  { q: "中国'海南自由贸易港'计划封关运作的目标年份是？", options: ["2025年", "2023年", "2028年", "2030年"], answer: 0, explanation: "海南自由贸易港计划2025年前适时启动封关运作。封关后海南将与境外实现'一线放开、二线管住'，与境外货物资金人员自由便利流动。海南自贸港是中国最大的自贸港和最高水平的开放形态。" },
  { q: "中国'世界环境日'是每年的？", options: ["6月5日", "4月22日", "3月22日", "5月31日"], answer: 0, explanation: "6月5日是'世界环境日'，1972年联合国大会确定。中国从1985年开始每年举办世界环境日活动。2024年世界环境日中国主题是'全面推进美丽中国建设'。世界环境日旨在提高全民环保意识。" },
  { q: "中国'植树节'是每年的？", options: ["3月12日", "4月22日", "3月22日", "5月31日"], answer: 0, explanation: "3月12日是中国的'植树节'。1979年全国人大常委会决定3月12日为中国植树节（孙中山逝世纪念日，孙中山生前大力提倡植树造林）。植树节旨在动员全民植树造林，绿化祖国，改善生态环境。" },
  { q: "中国'世界地球日'是每年的？", options: ["4月22日", "3月12日", "6月5日", "3月22日"], answer: 0, explanation: "4月22日是'世界地球日'，1970年发起，旨在唤起人类爱护地球、保护环境的意识。中国从1990年开始每年举办世界地球日活动。2024年世界地球日主题是'全球战塑'（减少塑料污染）。世界地球日是全球最大的环保活动之一。" },
  { q: "中国'世界水日'是每年的？", options: ["3月22日", "4月22日", "6月5日", "3月12日"], answer: 0, explanation: "3月22日是'世界水日'，1993年联合国大会确定。中国从1994年开始每年开展世界水日活动。世界水日旨在唤起公众的节水意识，加强水资源保护。中国'中国水周'为每年3月22-28日。" },
  { q: "中国'世界湿地日'是每年的？", options: ["2月2日", "3月22日", "6月5日", "4月22日"], answer: 0, explanation: "2月2日是'世界湿地日'，1996年确定（1971年2月2日《湿地公约》在伊朗拉姆萨尔签署）。中国1992年加入《湿地公约》。世界湿地日旨在宣传湿地保护的重要性。2021年起世界湿地日被联合国确定为国际日。" },
  { q: "中国'世界防治荒漠化和干旱日'是每年的？", options: ["6月17日", "6月5日", "3月22日", "4月22日"], answer: 0, explanation: "6月17日是'世界防治荒漠化和干旱日'，1995年联合国大会确定（1994年6月17日《联合国防治荒漠化公约》通过）。中国是受荒漠化影响最严重的国家之一，通过三北防护林等工程防治荒漠化取得显著成效。" },
  { q: "中国'世界海洋日'是每年的？", options: ["6月8日", "6月5日", "6月17日", "7月11日"], answer: 0, explanation: "6月8日是'世界海洋日'，2009年首次庆祝（2008年联合国大会确定）。中国从2008年开始举办世界海洋日活动。世界海洋日旨在提醒人们保护海洋环境，可持续利用海洋资源。中国海洋面积广阔，约300万平方千米。" },
  { q: "中国'国际生物多样性日'是每年的？", options: ["5月22日", "6月5日", "4月22日", "3月22日"], answer: 0, explanation: "5月22日是'国际生物多样性日'，2001年确定（1992年《生物多样性公约》通过）。中国是最早加入《生物多样性公约》的国家之一，2021年承办《生物多样性公约》第十五次缔约方大会（COP15）。" },
  { q: "中国'世界环境日'设立于哪一年？", options: ["1972年", "1970年", "1985年", "1992年"], answer: 0, explanation: "1972年6月5日联合国人类环境会议在斯德哥尔摩召开，这一天被定为'世界环境日'。中国从1985年开始每年举办世界环境日活动。2024年世界环境日中国主题是'全面推进美丽中国建设'。世界环境日旨在提高全民环保意识。" },
  { q: "中国'中国水周'是每年的？", options: ["3月22-28日", "3月12-18日", "6月5-11日", "4月22-28日"], answer: 0, explanation: "中国'中国水周'为每年3月22-28日，与'世界水日'（3月22日）同步。中国水周旨在唤起公众的节水意识，加强水资源保护。中国是世界上人均水资源最贫乏的国家之一，节水是中国基本国策。" },
  { q: "中国'中国植树节'设立于哪一年？", options: ["1979年", "1980年", "1985年", "1990年"], answer: 0, explanation: "1979年2月23日，第五届全国人大常委会第六次会议决定3月12日为中国植树节。3月12日是孙中山逝世纪念日（1925年3月12日），孙中山生前大力提倡植树造林。植树节旨在动员全民植树造林，绿化祖国。" },
  { q: "中国森林覆盖率约为？", options: ["约24%", "约15%", "约30%", "约20%"], answer: 0, explanation: "中国森林覆盖率约为24%，森林面积约2.2亿公顷，居世界第五。近年来中国持续推进国土绿化行动，森林覆盖率持续提高。中国是世界上森林面积增长最快的国家，年均新增森林面积居世界第一。中国目标是2035年森林覆盖率达到26%。" },
  { q: "中国是世界上森林面积增长最快的国家吗？", options: ["是", "不是", "不确定", "曾经是"], answer: 0, explanation: "中国是世界上森林面积增长最快的国家。根据联合国粮农组织数据，中国年均新增森林面积居世界第一。通过三北防护林、退耕还林等工程，中国森林覆盖率从20世纪80年代的约12%提高到目前的约24%，实现了'沙进人退'到'绿进沙退'的转变。" },
  { q: "中国是世界上人工林面积最大的国家吗？", options: ["是", "不是", "不确定", "曾经是"], answer: 0, explanation: "中国是世界上人工林面积最大的国家。中国人工林面积约8000万公顷，居世界第一。通过三北防护林、退耕还林等工程，中国大规模植树造林。人工林对增加森林覆盖率、防风固沙、保持水土和应对气候变化有重要作用。" },
  { q: "中国湿地保护率约为？", options: ["约50%以上", "约30%", "约40%", "约60%"], answer: 0, explanation: "中国湿地保护率约为50%以上。中国湿地面积约3.53亿亩，是世界上湿地面积最大的国家之一。近年来中国加大湿地保护力度，建立湿地自然保护区和国家湿地公园。2022年《湿地保护法》实施，湿地保护纳入法治轨道。" },
  { q: "中国是世界上湿地面积最大的国家之一吗？", options: ["是", "不是", "不确定", "曾经是"], answer: 0, explanation: "中国是世界上湿地面积最大的国家之一，湿地面积约3.53亿亩（约23.5万平方千米）。中国湿地类型多样，包括沼泽湿地、河流湿地、湖泊湿地、滨海湿地和人工湿地等。1992年中国加入《湿地公约》，现有64处国际重要湿地。" },
  { q: "中国'国家公园'与'自然保护区'的区别是？", options: ["国家公园保护更全面、层级更高", "自然保护区保护更全面", "两者完全相同", "国家公园只保护动物"], answer: 0, explanation: "国家公园相比自然保护区保护更全面、层级更高。国家公园保护大面积自然生态系统的完整性和原真性，兼顾科研、教育和游憩功能。自然保护区侧重特定物种或生态系统保护。国家公园体制整合了原有各类保护地。" },
  { q: "中国'生态文明建设示范区'数量已超过？", options: ["500个", "300个", "100个", "200个"], answer: 0, explanation: "截至2025年，中国已命名'生态文明建设示范区'超过500个（含市、县两级行政区）。生态文明建设示范区在生态制度、生态安全、生态经济、生态生活、生态文化等方面走在前列，是全国生态文明建设的标杆。" },
  { q: "中国'绿水青山就是金山银山'理念实践创新基地数量已超过？", options: ["70个", "50个", "30个", "100个"], answer: 0, explanation: "截至2025年，中国生态环境部已命名'绿水青山就是金山银山'实践创新基地超过70个。这些基地在生态产品价值实现、绿色低碳发展等方面探索经验，示范引领全国生态文明建设。" },
  { q: "中国'国土空间规划'的层级包括？", options: ["国家、省、市、县、乡五级", "国家和省两级", "国家、省、市三级", "省级和县级两级"], answer: 0, explanation: "中国国土空间规划分为国家、省、市、县、乡五级。国家级规划是全国国土空间开发保护的总体安排，省级规划落实国家规划要求，市县级规划是空间落实的关键，乡镇级规划是详细规划。五级规划自上而下、层层落实。" },
  { q: "中国'国土空间规划'的有效期一般为？", options: ["15年", "10年", "20年", "5年"], answer: 0, explanation: "国土空间规划期一般为15年（如2021-2035年），远期展望到2050年。规划每5年进行一次评估，可根据需要修改。国土空间规划是各类开发保护建设活动的依据，具有法定约束力。" },
  { q: "中国'多规合一'是指？", options: ["整合多种规划形成统一国土空间规划", "多种规划并行", "取消所有规划", "只保留城市规划"], answer: 0, explanation: "'多规合一'是指将原主体功能区规划、土地利用规划、城乡规划、海洋功能区划等多种规划整合为统一的国土空间规划。'多规合一'旨在解决规划冲突、提高空间治理效率，是国土空间规划体制改革的核心。" },
  { q: "中国'国土三调'是指？", options: ["第三次全国国土调查", "第三次全国土地调查", "第三次全国地理国情普查", "第三次全国农业普查"], answer: 0, explanation: "'国土三调'即第三次全国国土调查（原称第三次全国土地调查），2018年启动，2021年发布主要数据成果。调查全面查清了全国土地利用状况，为国土空间规划、自然资源管理和生态文明建设提供基础数据支撑。" },
  { q: "中国'永久基本农田'保护制度的核心是？", options: ["数量不减少、质量不降低、用途不改变", "只保数量", "只保质量", "可改变用途"], answer: 0, explanation: "永久基本农田保护制度的核心是'数量不减少、质量不降低、用途不改变'。永久基本农田是优质耕地，任何单位和个人不得擅自占用。国家实行永久基本农田特殊保护制度，确保国家粮食安全。" },
  { q: "中国'节约集约用地'制度的核心是？", options: ["严格控制建设用地总量", "扩大建设用地", "减少耕地", "以上都不对"], answer: 0, explanation: "节约集约用地制度的核心是严格控制建设用地总量，提高土地利用效率。中国以占世界9%的耕地养活世界18%的人口，人多地少的基本国情决定了必须实行最严格的节约用地制度。" },
  { q: "中国'国土空间生态修复'的重点区域不包括？", options: ["城市核心商务区", "矿山生态修复区", "湿地修复区", "海岸带修复区"], answer: 0, explanation: "国土空间生态修复的重点区域包括矿山生态修复区、湿地修复区、海岸带修复区、荒漠化防治区、水土流失治理区等。城市核心商务区不是生态修复的重点区域，生态修复主要针对受损或退化的自然生态系统。" },
  { q: "中国'国家公园'体制的设立标志着什么？", options: ["自然保护地体系进入新阶段", "取消自然保护区", "减少生态保护面积", "以上都不对"], answer: 0, explanation: "2021年中国首批国家公园的设立标志着中国自然保护地体系进入新阶段。国家公园体制是在原有自然保护区基础上整合升级，建立以国家公园为主体的自然保护地体系，更科学有效地保护自然生态系统的完整性和原真性。" },
  { q: "中国'碳达峰碳中和'目标的简称是？", options: ["3060目标", "2050目标", "2035目标", "2060目标"], answer: 0, explanation: "中国'碳达峰碳中和'目标简称'3060'目标，即2030年前实现碳达峰、2060年前实现碳中和。2020年9月习近平在联合国大会一般性辩论上宣布。'3060'目标是中国应对气候变化、推动绿色低碳发展的战略目标。" },
  { q: "中国'碳排放权交易市场'是全球覆盖温室气体排放量最大的吗？", options: ["是", "不是", "不确定", "曾经是"], answer: 0, explanation: "中国全国碳排放权交易市场（全国碳市场）是全球覆盖温室气体排放量最大的碳市场。2021年7月上线交易，首批纳入发电行业，覆盖约45亿吨CO2排放。后续将逐步扩大到建材、有色、钢铁等行业。全国碳市场是中国实现双碳目标的重要市场机制。" },
  { q: "中国是世界上最大的可再生能源生产国吗？", options: ["是", "不是", "不确定", "曾经是"], answer: 0, explanation: "中国是世界上最大的可再生能源生产国。中国在风能、太阳能、水能等可再生能源的装机容量和发电量均居世界第一。中国水电装机容量约390GW（世界第一）、风电约365GW（世界第一）、太阳能约430GW（世界第一）。" },
  { q: "中国是世界上最大的太阳能光伏生产国吗？", options: ["是", "不是", "不确定", "曾经是"], answer: 0, explanation: "中国是世界上最大的太阳能光伏生产国和装机国。中国太阳能光伏组件产量占全球约80%，太阳能装机容量约430GW（世界第一）。中国光伏企业在全球光伏产业链中占主导地位。中国目标是2030年风电和太阳能装机达到1200GW以上。" },
  { q: "中国是世界上最大的风电装机国吗？", options: ["是", "不是", "不确定", "曾经是"], answer: 0, explanation: "中国是世界上最大的风电装机国，风电装机容量约365GW（世界第一）。中国陆上风电和海上风电装机均居世界第一。中国风电装备制造能力居世界前列。中国目标是2030年风电和太阳能装机达到1200GW以上。" },
  { q: "中国是世界上最大的水电装机国吗？", options: ["是", "不是", "不确定", "曾经是"], answer: 0, explanation: "中国是世界上最大的水电装机国，水电装机容量约390GW（世界第一）。中国三峡大坝是世界上最大的水电站，装机容量22500兆瓦。中国水电年发电量约1300TWh，占中国发电量约16%。水电是中国最重要的可再生能源。" },
  { q: "中国是世界上最大的新能源汽车生产国吗？", options: ["是", "不是", "不确定", "曾经是"], answer: 0, explanation: "中国是世界上最大的新能源汽车生产国和消费国。2024年中国新能源汽车产销量超过1000万辆，占全球约60%。中国新能源汽车产业链完整，技术水平世界领先。中国目标是2025年新能源汽车销量占比达到20%以上（已超额完成）。" },
  { q: "中国是世界上最大的电动汽车电池生产国吗？", options: ["是", "不是", "不确定", "曾经是"], answer: 0, explanation: "中国是世界上最大的电动汽车电池生产国。中国企业（宁德时代、比亚迪等）动力电池产量占全球约70%。宁德时代是全球最大的动力电池制造商。中国动力电池技术世界领先，产业链完整。电动汽车电池是新能源汽车的核心部件。" },
  { q: "中国'双碳'目标的实现路径不包括？", options: ["增加化石燃料使用", "发展可再生能源", "提高能源效率", "增加碳汇"], answer: 0, explanation: "中国'双碳'目标的实现路径包括发展可再生能源、提高能源效率、增加碳汇（植树造林）、碳捕集利用与封存（CCUS）等。增加化石燃料使用会加剧碳排放，不利于实现双碳目标，不属于实现路径。" },
  { q: "中国'碳汇'主要来自？", options: ["森林和湿地", "工业", "农业", "城市"], answer: 0, explanation: "中国碳汇主要来自森林和湿地。森林通过光合作用吸收CO2，是重要的自然碳汇。湿地也有固碳功能。中国通过植树造林和湿地保护增加碳汇。2020年中国森林碳汇约12亿吨CO2，是中国实现碳中和目标的重要自然解决方案。" },
  { q: "中国'碳捕集利用与封存'（CCUS）技术是指？", options: ["捕集CO2并利用或封存", "减少能源消耗", "增加可再生能源", "减少森林砍伐"], answer: 0, explanation: "碳捕集利用与封存（CCUS）技术是指将CO2从排放源捕集，进行利用或封存，减少CO2排放到大气中。CCUS是实现碳中和的重要技术手段，特别适用于钢铁、水泥等难减排行业。中国正在多个地区建设CCUS示范项目。" },
  { q: "中国'绿色低碳发展'的核心是？", options: ["减少碳排放，发展绿色经济", "增加能源消耗", "减少经济总量", "取消所有工业"], answer: 0, explanation: "绿色低碳发展的核心是减少碳排放，发展绿色经济。通过能源结构调整、产业结构优化、技术进步和制度创新，实现经济增长与碳排放脱钩。中国'十四五'规划提出经济社会发展全面绿色转型，推动高质量发展。" },
  { q: "中国'能源革命'的核心是？", options: ["能源结构转型，发展清洁能源", "增加煤炭使用", "减少能源供应", "取消所有化石能源"], answer: 0, explanation: "能源革命的核心是能源结构转型，发展清洁能源，减少化石能源依赖。中国能源革命包括消费革命（节能提效）、供给革命（清洁能源）、技术革命和体制革命。中国目标是2030年非化石能源占比达到25%以上。" },
  { q: "中国'循环经济'的核心是？", options: ["资源高效利用和循环利用", "增加资源消耗", "减少经济总量", "取消所有工业"], answer: 0, explanation: "循环经济的核心是资源高效利用和循环利用，实现'减量化、再利用、资源化'。循环经济是绿色低碳发展的重要途径。中国2008年通过《循环经济促进法》，在工业园区、城市和社会层面推进循环经济发展。" },
  { q: "中国'无废城市'建设的核心是？", options: ["固体废物源头减量和资源化利用", "取消所有垃圾", "增加垃圾填埋", "减少城市人口"], answer: 0, explanation: "'无废城市'建设的核心是固体废物源头减量和资源化利用，最大限度减少填埋量。无废城市不是没有固体废物，而是通过源头减量、分类回收和资源化利用，实现固体废物环境影响最小化。中国已在多个城市开展'无废城市'建设试点。" },
  { q: "中国'垃圾分类'政策全面推行的标志是？", options: ["2019年上海强制垃圾分类", "2018年北京垃圾分类", "2020年全国垃圾分类", "2017年深圳垃圾分类"], answer: 0, explanation: "2019年7月1日《上海市生活垃圾管理条例》实施，标志着中国城市强制垃圾分类正式开始。上海是中国首个强制垃圾分类的特大城市。此后北京、广州等城市也相继实施垃圾分类。垃圾分类是实现'无废城市'的重要基础。" },
  { q: "中国'限塑令'最早实施于哪一年？", options: ["2008年", "2006年", "2010年", "2020年"], answer: 0, explanation: "中国'限塑令'最早于2008年6月1日实施，规定在全国范围内禁止生产、销售和使用厚度小于0.025毫米的塑料购物袋，实行有偿使用制度。2020年中国进一步发布'限塑令'升级版，限制一次性塑料制品的使用。" },
  { q: "中国'限塑令'升级版发布于哪一年？", options: ["2020年", "2018年", "2019年", "2021年"], answer: 0, explanation: "2020年1月，中国发布《关于进一步加强塑料污染治理的意见》，即'限塑令'升级版。该意见对一次性塑料制品分阶段禁止和限制使用。到2025年，塑料制品生产、流通、消费和回收处置等环节的管理制度基本建立。" },
  { q: "中国'长江十年禁渔'开始于哪一年？", options: ["2021年", "2019年", "2020年", "2022年"], answer: 0, explanation: "2021年1月1日，中国实施长江十年禁渔计划。长江流域332个水生生物保护区实行全面禁捕，长江干流和重要支流除保护区外暂定实行10年禁捕。长江十年禁渔是保护长江水生生物多样性的重大举措。" },
  { q: "中国'长江十年禁渔'的禁捕期限是？", options: ["10年", "5年", "20年", "永久"], answer: 0, explanation: "中国'长江十年禁渔'的禁捕期限为10年（2021-2030年）。长江流域干流和重要支流暂定实行10年禁捕。十年禁渔旨在恢复长江水生生物资源，保护长江水生生物多样性。长江十年禁渔是保护长江母亲河的重大举措。" },
  { q: "中国'黄河流域生态保护和高质量发展'上升为国家战略的时间是？", options: ["2019年", "2017年", "2018年", "2020年"], answer: 0, explanation: "2019年9月，黄河流域生态保护和高质量发展上升为国家战略。黄河流域生态保护强调'重在保护，要在治理'。2022年《黄河保护法》通过，2023年4月实施。黄河流域是中国重要的生态屏障和经济区。" },
  { q: "中国'长江经济带'发展战略提出于哪一年？", options: ["2014年", "2012年", "2015年", "2016年"], answer: 0, explanation: "2014年，中国提出长江经济带发展战略。长江经济带覆盖上海、江苏、浙江、安徽、江西、湖北、湖南、重庆、四川、云南、贵州等11省市。长江经济带发展战略强调'共抓大保护、不搞大开发'，推动绿色发展。" },
  { q: "中国'长江经济带'覆盖多少个省市？", options: ["11个", "9个", "10个", "12个"], answer: 0, explanation: "长江经济带覆盖11个省市：上海、江苏、浙江、安徽、江西、湖北、湖南、重庆、四川、云南、贵州。长江经济带面积约205万平方千米，人口和经济总量均超过全国的40%，是中国最大的经济区域。" },
  { q: "中国'黄河流域生态保护'的核心理念是？", options: ["重在保护，要在治理", "重在开发", "重在灌溉", "重在防洪"], answer: 0, explanation: "黄河流域生态保护的核心理念是'重在保护，要在治理'。强调黄河流域生态系统的整体保护和系统治理，统筹推进山水林田湖草沙冰综合治理。2023年《黄河保护法》实施，将黄河流域生态保护纳入法治轨道。" },
  { q: "中国'河长制'的核心是？", options: ["各级党政负责人担任河长", "民间志愿者担任河长", "企业负责河湖管理", "环保部门独立管理"], answer: 0, explanation: "河长制的核心是由各级党政负责人担任河长，负责河湖管理和保护。河长制建立了省、市、县、乡、村五级河长体系。河长制是中国水治理体制的重要创新，实现了河湖管理责任到人。2018年全面推行河长制。" },
  { q: "中国'林长制'的核心是？", options: ["各级党政负责人担任林长", "民间志愿者担任林长", "企业负责森林管理", "林业部门独立管理"], answer: 0, explanation: "林长制的核心是由各级党政负责人担任林长，负责森林草原资源保护发展。林长制建立了省、市、县、乡、村五级林长体系。林长制是中国生态文明制度的重要创新，实现了森林草原管理责任到人。2021年全面推行林长制。" },
  { q: "中国'生态保护红线'制度的核心是？", options: ["划定生态功能保障基线", "划定开发边界", "划定城市边界", "划定农业用地"], answer: 0, explanation: "生态保护红线制度的核心是划定生态功能保障基线，在生态空间范围内具有特殊重要生态功能、必须严格保护的区域。生态保护红线是中国生态环境保护的制度创新，纳入国土空间规划体系，实行严格管控。" },
  { q: "中国'三线一单'制度中的'三线'不包括？", options: ["城市建设红线", "生态保护红线", "环境质量底线", "资源利用上线"], answer: 0, explanation: "'三线一单'中的'三线'指生态保护红线、环境质量底线和资源利用上线，'一单'指生态环境准入清单。城市建设红线不属于'三线'范畴。'三线一单'是生态环境分区管控体系，是推动高质量发展的制度保障。" },
  { q: "中国'生态文明建设'写入宪法的时间是？", options: ["2018年", "2016年", "2017年", "2019年"], answer: 0, explanation: "2018年3月，十三届全国人大一次会议通过宪法修正案，将'生态文明建设'写入宪法序言。这标志着生态文明建设上升为国家意志和宪法原则。中国是首个将生态文明建设写入宪法的国家，体现了对生态环境保护的高度重视。" },
  { q: "中国'绿水青山就是金山银山'理念提出于？", options: ["2005年浙江安吉", "2010年北京", "2015年巴黎", "2018年全国人大"], answer: 0, explanation: "2005年8月，习近平在浙江安吉余村考察时提出'绿水青山就是金山银山'理念。2017年该理念写入十九大报告和新党章。这一理念强调生态环境保护和经济发展的辩证统一关系，是习近平生态文明思想的核心内容。" },
  { q: "中国'生态环境损害赔偿制度'的目的是？", options: ["追究破坏生态环境的责任", "增加政府收入", "减少企业数量", "取消经济发展"], answer: 0, explanation: "生态环境损害赔偿制度的目的是追究破坏生态环境的责任，'谁污染谁治理、谁破坏谁修复'。2017年起在全国试行，2022年全面推行。该制度旨在解决'企业污染、群众受害、政府买单'的困局，推动生态环境修复。" },
  { q: "中国'中央生态环境保护督察'开始于？", options: ["2016年", "2014年", "2018年", "2020年"], answer: 0, explanation: "中央生态环境保护督察始于2016年（原名'中央环保督察'），2019年改为'中央生态环境保护督察'。督察组代表党中央对各省区市开展生态环境保护督察，是中国生态环境监管体制的重大创新。已实现对所有省份的全覆盖督察。" },
  { q: "中国'排污许可制度'的特点是？", options: ["一证式管理", "多头管理", "自愿申请", "无约束力"], answer: 0, explanation: "排污许可制度的特点是'一证式'管理，即一个排污单位只申领一个排污许可证，涵盖所有污染物排放。2021年《排污许可管理条例》施行。排污许可制度是固定污染源管理的核心制度，实现'一证式'全过程管理。" },
  { q: "中国'环境影响评价制度'的法律依据是？", options: ["《环境影响评价法》", "《环境保护法》", "《大气污染防治法》", "《水污染防治法》"], answer: 0, explanation: "环境影响评价制度的主要法律依据是《环境影响评价法》（2002年通过，2016年、2018年修订）。环评制度要求建设项目和规划在实施前进行环境影响评价。2018年环评资质取消，强化了事中事后监管。环评是预防环境污染的第一道防线。" },
  { q: "中国'大气十条'的正式名称是？", options: ["《大气污染防治行动计划》", "《大气十条》", "《清洁空气法》", "《蓝天保卫战计划》"], answer: 0, explanation: "'大气十条'的正式名称是《大气污染防治行动计划》（2013年9月发布）。'大气十条'要求到2017年京津冀、长三角、珠三角PM2.5浓度大幅下降。2018年'大气十条'升级为《打赢蓝天保卫战三年行动计划》。" },
  { q: "中国'水十条'的正式名称是？", options: ["《水污染防治行动计划》", "《水十条》", "《清洁水法》", "《碧水保卫战计划》"], answer: 0, explanation: "'水十条'的正式名称是《水污染防治行动计划》（2015年4月发布）。'水十条'要求到2020年全国水环境质量得到阶段性改善。'水十条'提出了全面控制污染物排放、推动经济转型升级等十项措施。" },
  { q: "中国'土十条'的正式名称是？", options: ["《土壤污染防治行动计划》", "《土十条》", "《清洁土壤法》", "《净土保卫战计划》"], answer: 0, explanation: "'土十条'的正式名称是《土壤污染防治行动计划》（2016年5月发布）。'土十条'要求到2020年土壤环境质量总体保持稳定。2019年1月1日《土壤污染防治法》施行。土壤污染防治重点在农用地和建设用地。" },
  { q: "中国'蓝天保卫战'是哪三个保卫战之一？", options: ["蓝天、碧水、净土", "蓝天、绿水、青山", "空气、水、土", "大气、海洋、森林"], answer: 0, explanation: "党的十九大提出打好污染防治攻坚战，包括'蓝天保卫战''碧水保卫战''净土保卫战'三大保卫战。蓝天保卫战聚焦大气污染治理，碧水保卫战聚焦水污染治理，净土保卫战聚焦土壤污染治理。这是中国污染防治的核心部署。" },
  { q: "中国'PM2.5'的主要来源不包括？", options: ["汽车尾气", "燃煤", "工业排放", "植物光合作用"], answer: 3, explanation: "PM2.5（细颗粒物）的主要来源包括燃煤、汽车尾气、工业排放、扬尘、生物质燃烧等。植物光合作用是植物吸收CO2释放O2的过程，不是PM2.5的来源。PM2.5是大气污染的重要指标，危害人体健康。" },
  { q: "中国'雾霾'的主要成分不包括？", options: ["氧气", "PM2.5", "二氧化硫", "氮氧化物"], answer: 0, explanation: "雾霾的主要成分包括PM2.5（细颗粒物）、二氧化硫、氮氧化物、挥发性有机物等污染物。氧气是空气的正常成分（占21%），不是雾霾的成分。雾霾是大气污染的极端表现，对呼吸系统和心血管系统有害。" },
  { q: "中国'臭氧污染'主要发生在哪个季节？", options: ["夏季", "冬季", "春季", "秋季"], answer: 0, explanation: "臭氧污染主要发生在夏季。夏季高温强日照条件下，氮氧化物和挥发性有机物在光化学反应下生成臭氧。近地面臭氧是一种二次污染物，对呼吸系统和眼睛有刺激作用。臭氧污染是夏季大气污染的主要特征，与冬季PM2.5污染形成对比。" },
  { q: "中国'酸雨'的主要成因是？", options: ["二氧化硫和氮氧化物排放", "二氧化碳排放", "甲烷排放", "氟利昂排放"], answer: 0, explanation: "酸雨的主要成因是人类活动排放的二氧化硫（SO2）和氮氧化物（NOx）在大气中与水蒸气反应生成硫酸和硝酸，随降水落到地面。酸雨危害森林、土壤和水体。中国酸雨主要分布在南方地区，近年来酸雨面积和频率大幅下降。" },
  { q: "中国'富营养化'主要发生在？", options: ["湖泊和近海", "河流上游", "地下水", "冰川"], answer: 0, explanation: "富营养化主要发生在湖泊和近海。富营养化是水体中氮、磷等营养物质过剩，导致藻类大量繁殖，消耗水中溶解氧，造成鱼类死亡。中国太湖、巢湖、滇池等湖泊和渤海湾等近海曾发生富营养化问题。富营养化的主要来源是农业面源污染和生活污水。" },
  { q: "中国'赤潮'发生在？", options: ["海洋", "河流", "湖泊", "地下水"], answer: 0, explanation: "赤潮发生在海洋中，是海水中某些浮游植物、原生动物或细菌在一定环境条件下爆发性增殖或高度聚集，引起水体变色的现象。赤潮的主要成因是海水富营养化。赤潮危害海洋生态和渔业，产生的毒素可经食物链危害人体健康。" },
  { q: "中国'水华'发生在？", options: ["淡水湖泊", "海洋", "河流", "地下水"], answer: 0, explanation: "水华发生在淡水湖泊中，是淡水水体中藻类大量繁殖，在水面形成绿色藻层的现象。水华的成因与赤潮类似，主要是水体富营养化。中国太湖、滇池、巢湖等湖泊夏季易发生水华。水华危害饮用水安全和湖泊生态。" },
  { q: "中国'地下水超采'最严重的地区是？", options: ["华北平原", "长江中下游", "四川盆地", "珠江三角洲"], answer: 0, explanation: "华北平原是中国地下水超采最严重的地区。华北平原是中国重要的粮食产区，农业灌溉大量抽取地下水，导致地下水位持续下降，形成大面积地下水漏斗区。南水北调工程缓解了华北水资源紧张状况，华北地区已实施地下水超采综合治理。" },
  { q: "中国'南水北调'工程的路线不包括？", options: ["西线", "北线", "东线", "中线"], answer: 1, explanation: "南水北调工程包括东线、中线和西线三条调水路线。东线从扬州江都抽水北送至山东、天津；中线从丹江口水库调水至北京、天津；西线从长江上游调水至黄河上游。没有'北线'。东线2013年通水，中线2014年通水，西线尚未开工建设。" },
  { q: "中国'海绵城市'建设的核心是？", options: ["城市像海绵一样吸水蓄水", "增加城市硬地面", "减少城市绿地", "扩大城市排水管道"], answer: 0, explanation: "海绵城市建设的核心是让城市像海绵一样吸水、蓄水、渗水、净水，需要时释放利用。通过建设绿色屋顶、下沉式绿地、透水铺装等，实现雨水源头减排。2015年起在30个城市开展海绵城市建设试点。海绵城市是应对城市内涝的重要举措。" },
  { q: "中国'退耕还林还草'工程主要在？", options: ["水土流失严重地区", "平原地区", "城市地区", "沿海地区"], answer: 0, explanation: "退耕还林还草工程主要在陡坡耕地、水土流失严重地区、沙漠化地区实施。1999年开始试点，2002年全面实施。退耕还林还草是中国最大的生态建设工程，累计退耕面积约2900万公顷。退耕还林还草改善了生态环境，也促进了农民增收。" },
  { q: "中国'天然林保护工程'的实施范围是？", options: ["全国", "仅东北地区", "仅西南地区", "仅华南地区"], answer: 0, explanation: "天然林保护工程在全国范围内实施。2000年正式启动，2014年全面停止天然林商业性采伐。天然林保护工程覆盖全国，重点在东北、西南等天然林集中分布区。天然林保护工程是中国最大的森林保护工程，有效保护了全国天然林资源。" },
  { q: "中国'三北防护林'工程的范围是？", options: ["东北、华北、西北", "华南、华东、华中", "西南、西北、华南", "东北、华东、西南"], answer: 0, explanation: "三北防护林工程覆盖东北、华北、西北13个省份，1978年启动，预计2050年完成。三北防护林工程是中国最大的生态建设工程之一，旨在防治沙漠化、水土流失和农田防护。三北工程累计造林保存面积超过3000万公顷。" },
  { q: "中国'防沙治沙法'颁布于？", options: ["2001年", "1999年", "2003年", "2005年"], answer: 0, explanation: "《防沙治沙法》于2001年8月通过，2002年1月1日施行。这是世界上首部防沙治沙专门法律。《防沙治沙法》明确了防沙治沙的原则、规划、措施和法律责任。中国荒漠化面积持续减少，实现了从'沙进人退'到'人进沙退'的转变。" },
];
